create table public."cross_modal_states" (
  "id" uuid default gen_random_uuid() not null,
  "twin_id" uuid not null,
  "evaluated_at" timestamp with time zone default now() not null,
  "theta_power" real not null,
  "alpha_power" real not null,
  "theta_alpha_ratio" real generated always as ((theta_power / alpha_power)) stored,
  "frontal_alpha_asymmetry" real,
  "hrv_lf_power" real not null,
  "hrv_hf_power" real not null,
  "hrv_lf_hf_ratio" real generated always as ((hrv_lf_power / hrv_hf_power)) stored,
  "phase_ripple_heart_rad" real,
  "phase_ripple_breath_rad" real,
  "stress_confirmed" boolean generated always as ((((theta_power / alpha_power) >= (0.62)::double precision) AND ((hrv_lf_power / hrv_hf_power) >= (2.1)::double precision))) stored,
  "valence_score" real,
  "stress_level" stress_state default 'CALM'::stress_state not null,
  "fraud_score_threshold_override" real generated always as (
CASE
    WHEN (((hrv_lf_power / hrv_hf_power) > (3.5)::double precision) OR ((theta_power / alpha_power) > (0.80)::double precision)) THEN NULL::numeric
    WHEN (((theta_power / alpha_power) >= (0.62)::double precision) AND ((hrv_lf_power / hrv_hf_power) >= (2.1)::double precision)) THEN 0.25
    ELSE 0.1
END) stored,
  "eeg_reading_id" bigint,
  "hrv_reading_id" bigint,
  "relay_path_id" bigint,
  constraint "cross_modal_states_alpha_power_check" CHECK ((alpha_power > (0)::double precision)),
  constraint "cross_modal_states_hrv_hf_power_check" CHECK ((hrv_hf_power > (0)::double precision)),
  constraint "cross_modal_states_hrv_lf_power_check" CHECK ((hrv_lf_power >= (0)::double precision)),
  constraint "cross_modal_states_theta_power_check" CHECK ((theta_power >= (0)::double precision)),
  constraint "cross_modal_states_eeg_reading_id_fkey" FOREIGN KEY (eeg_reading_id) REFERENCES mesh_node_readings(id),
  constraint "cross_modal_states_hrv_reading_id_fkey" FOREIGN KEY (hrv_reading_id) REFERENCES mesh_node_readings(id),
  constraint "cross_modal_states_relay_path_id_fkey" FOREIGN KEY (relay_path_id) REFERENCES relay_path_events(id),
  constraint "cross_modal_states_twin_id_fkey" FOREIGN KEY (twin_id) REFERENCES twin_identity(id) ON DELETE CASCADE,
  constraint "cross_modal_states_pkey" PRIMARY KEY (id)
);

