  "id" bigint default nextval('faa_readings_id_seq'::regclass) not null,
  "twin_id" uuid not null,
  "node_id" smallint,
  "measured_at" timestamp with time zone default now() not null,
  "session_id" uuid,
  "channel_count" smallint default 24 not null,
  "sample_rate_hz" real default 256.0 not null,
  "window_len_ms" integer default 1000 not null,
  "f3_alpha_power_uv2" real not null,
  "f4_alpha_power_uv2" real not null,
  "faa_raw" real generated always as ((ln((f4_alpha_power_uv2)::double precision) - ln((f3_alpha_power_uv2)::double precision))) stored,
  "valence_score" real,
  "fz_theta_power_uv2" real,
  "fz_alpha_power_uv2" real,
  "theta_alpha_ratio" real generated always as (
CASE
    WHEN (fz_alpha_power_uv2 > (0)::double precision) THEN (fz_theta_power_uv2 / fz_alpha_power_uv2)
    ELSE NULL::real
END) stored,
  "arousal_score" real,
  "gsr_reading_id" bigint,
  "cross_modal_id" uuid,
  constraint "faa_readings_arousal_score_check" CHECK (((arousal_score >= (0.0)::double precision) AND (arousal_score <= (1.0)::double precision))),
  constraint "faa_readings_f3_alpha_power_uv2_check" CHECK ((f3_alpha_power_uv2 > (0)::double precision)),
  constraint "faa_readings_f4_alpha_power_uv2_check" CHECK ((f4_alpha_power_uv2 > (0)::double precision)),
  constraint "faa_readings_fz_alpha_power_uv2_check" CHECK ((fz_alpha_power_uv2 > (0)::double precision)),
  constraint "faa_readings_fz_theta_power_uv2_check" CHECK ((fz_theta_power_uv2 >= (0)::double precision)),
  constraint "faa_readings_valence_score_check" CHECK (((valence_score >= ('-1.0'::numeric)::double precision) AND (valence_score <= (1.0)::double precision))),
  constraint "faa_readings_cross_modal_id_fkey" FOREIGN KEY (cross_modal_id) REFERENCES cross_modal_states(id),
  constraint "faa_readings_gsr_reading_id_fkey" FOREIGN KEY (gsr_reading_id) REFERENCES gsr_readings(id),
  constraint "faa_readings_node_id_fkey" FOREIGN KEY (node_id) REFERENCES mesh_nodes(id),
  constraint "faa_readings_session_id_fkey" FOREIGN KEY (session_id) REFERENCES edge_gateway_sessions(id),
  constraint "faa_readings_twin_id_fkey" FOREIGN KEY (twin_id) REFERENCES twin_identity(id) ON DELETE CASCADE,
  constraint "faa_readings_pkey" PRIMARY KEY (id)
);

create table public."frequency_peaks" (
  "id" bigint default nextval('frequency_peaks_id_seq'::regclass) not null,
