  "is_dna_resonance" boolean generated always as (((peak_freq_mhz >= 10229.0) AND (peak_freq_mhz <= 10271.0))) stored,
  "is_uwb_band" boolean generated always as (((peak_freq_mhz >= 6000.0) AND (peak_freq_mhz <= 8500.0))) stored,
