  "propagation_medium" text default 'skin'::text not null,
  "conductivity_proxy_s_m" real not null,
  "conductivity_baseline" real,
  "conductivity_delta" real generated always as ((conductivity_proxy_s_m - COALESCE(conductivity_baseline, (0)::real))) stored,
  "gsr_stress_label" text generated always as (
CASE
    WHEN (conductivity_proxy_s_m < (0.5)::double precision) THEN 'CALM'::text
    WHEN (conductivity_proxy_s_m < (1.5)::double precision) THEN 'MILD_AROUSAL'::text
    WHEN (conductivity_proxy_s_m < (2.5)::double precision) THEN 'STRESS'::text
    ELSE 'ACUTE_STRESS'::text
END) stored,
  "gnuradio_flowgraph" text,
  "kalman_gain" real,
  "snr_db" real,
  "cross_modal_state_id" uuid,
  constraint "gsr_readings_cross_modal_state_id_fkey" FOREIGN KEY (cross_modal_state_id) REFERENCES cross_modal_states(id),
  constraint "gsr_readings_dest_node_id_fkey" FOREIGN KEY (dest_node_id) REFERENCES mesh_nodes(id),
  constraint "gsr_readings_session_id_fkey" FOREIGN KEY (session_id) REFERENCES edge_gateway_sessions(id),
  constraint "gsr_readings_source_node_id_fkey" FOREIGN KEY (source_node_id) REFERENCES mesh_nodes(id),
  constraint "gsr_readings_twin_id_fkey" FOREIGN KEY (twin_id) REFERENCES twin_identity(id) ON DELETE CASCADE,
  constraint "gsr_readings_pkey" PRIMARY KEY (id)
);

