create table public."p2p_connections" (
  "id" bigint generated always as identity not null,
  "twin_id_a" uuid not null,
  "twin_id_b" uuid not null,
  "state" p2p_connection_state default 'pending'::p2p_connection_state not null,
  "freq_a_ghz" real,
  "freq_b_ghz" real,
  "freq_delta_ghz" real generated always as (abs((freq_a_ghz - freq_b_ghz))) stored,
  "consent_a_at" timestamp with time zone,
  "consent_b_at" timestamp with time zone,
  "revoked_by" uuid,
  "revoked_at" timestamp with time zone,
  "revocation_reason" text,
  "initiated_at" timestamp with time zone default now() not null,
  "activated_at" timestamp with time zone,
  constraint "p2p_connections_no_self" CHECK ((twin_id_a <> twin_id_b)),
  constraint "p2p_connections_ordered" CHECK ((twin_id_a < twin_id_b)),
  constraint "p2p_connections_rf_range" CHECK (((freq_delta_ghz IS NULL) OR (freq_delta_ghz < (0.05)::double precision))),
  constraint "p2p_connections_revoked_by_fkey" FOREIGN KEY (revoked_by) REFERENCES twin_identity(id),
  constraint "p2p_connections_twin_id_a_fkey" FOREIGN KEY (twin_id_a) REFERENCES twin_identity(id) ON DELETE CASCADE,
  constraint "p2p_connections_twin_id_b_fkey" FOREIGN KEY (twin_id_b) REFERENCES twin_identity(id) ON DELETE CASCADE,
  constraint "p2p_connections_pkey" PRIMARY KEY (id),
  constraint "p2p_connections_unique" UNIQUE (twin_id_a, twin_id_b)
);

