  constraint "p2p_handshakes_initiator_twin_id_fkey" FOREIGN KEY (initiator_twin_id) REFERENCES twin_identity(id) ON DELETE CASCADE,
  constraint "p2p_handshakes_responder_twin_id_fkey" FOREIGN KEY (responder_twin_id) REFERENCES twin_identity(id) ON DELETE CASCADE,
  constraint "p2p_handshakes_pkey" PRIMARY KEY (id),
