  constraint "research_runs_topic_id_fkey" FOREIGN KEY (topic_id) REFERENCES research_topics(id) ON DELETE SET NULL,
  constraint "research_runs_twin_id_fkey" FOREIGN KEY (twin_id) REFERENCES twin_identity(id) ON DELETE SET NULL,
  constraint "research_runs_pkey" PRIMARY KEY (id),
  constraint "research_runs_agent_id_cycle_key" UNIQUE (agent_id, cycle)
);

create table public."research_summaries" (
