  "input_hash" text not null,
  "created_at" timestamp with time zone default now() not null,
  constraint "research_summaries_agent_id_fkey" FOREIGN KEY (agent_id) REFERENCES agents(node_id) ON DELETE CASCADE,
  constraint "research_summaries_topic_id_fkey" FOREIGN KEY (topic_id) REFERENCES research_topics(id) ON DELETE SET NULL,
  constraint "research_summaries_pkey" PRIMARY KEY (id),
  constraint "research_summaries_agent_id_input_hash_key" UNIQUE (agent_id, input_hash)
