  "discovered_by" text,
  "created_at" timestamp with time zone default now() not null,
  "explored_at" timestamp with time zone,
  constraint "research_topics_status_check" CHECK ((status = ANY (ARRAY['queued'::text, 'explored'::text, 'dropped'::text]))),
  constraint "research_topics_discovered_by_fkey" FOREIGN KEY (discovered_by) REFERENCES agents(node_id) ON DELETE SET NULL,
  constraint "research_topics_parent_topic_id_fkey" FOREIGN KEY (parent_topic_id) REFERENCES research_topics(id) ON DELETE SET NULL,
  constraint "research_topics_pkey" PRIMARY KEY (id),
  constraint "research_topics_topic_biomarker_key" UNIQUE (topic, biomarker)
);

create table public."rna_interference_log" (
  "id" bigint generated always as identity not null,
  "twin_id" uuid not null,
  "sirna_molecule_id" bigint not null,
  "target_molecule_id" bigint not null,
  "silencing_efficiency" real not null,
  "off_target_score" real default 0.0 not null,
  "target_node_id" smallint,
  "node_signal_suppression" real,
  "estimated_duration_h" real,
  "applied_at" timestamp with time zone default now() not null,
  "expires_at" timestamp with time zone,
  "effect_duration" bio_effect_duration default 'hours'::bio_effect_duration not null,
  "node_effect" node_effect_type default 'node_silencing'::node_effect_type not null,
  constraint "rna_interference_log_off_target_score_check" CHECK (((off_target_score >= (0.0)::double precision) AND (off_target_score <= (1.0)::double precision))),
  constraint "rna_interference_log_silencing_efficiency_check" CHECK (((silencing_efficiency >= (0.0)::double precision) AND (silencing_efficiency <= (1.0)::double precision))),
  constraint "rna_interference_log_sirna_molecule_id_fkey" FOREIGN KEY (sirna_molecule_id) REFERENCES bio_molecule_registry(id),
  constraint "rna_interference_log_target_molecule_id_fkey" FOREIGN KEY (target_molecule_id) REFERENCES bio_molecule_registry(id),
  constraint "rna_interference_log_target_node_id_fkey" FOREIGN KEY (target_node_id) REFERENCES mesh_nodes(id),
  constraint "rna_interference_log_twin_id_fkey" FOREIGN KEY (twin_id) REFERENCES twin_identity(id) ON DELETE CASCADE,
  constraint "rna_interference_log_pkey" PRIMARY KEY (id)
);

