  "node_effect" node_effect_type default 'temporary_modulation'::node_effect_type not null,
  constraint "rna_translation_events_translation_efficiency_check" CHECK (((translation_efficiency >= (0.0)::double precision) AND (translation_efficiency <= (1.0)::double precision))),
  constraint "rna_translation_events_target_node_id_fkey" FOREIGN KEY (target_node_id) REFERENCES mesh_nodes(id),
  constraint "rna_translation_events_template_molecule_id_fkey" FOREIGN KEY (template_molecule_id) REFERENCES bio_molecule_registry(id),
  constraint "rna_translation_events_twin_id_fkey" FOREIGN KEY (twin_id) REFERENCES twin_identity(id) ON DELETE CASCADE,
