  "path_loss_air_db" real default 48.0 not null,
  "path_loss_body_coupled_db" real,
  "bio_doppler_baseline_hz" real,
  "bio_doppler_std_hz" real,
  "reflection_sources" text[] default ARRAY['heart'::text, 'lungs'::text] not null,
