  "prf_jitter_ms" real default 0.0,
  "prf_jitter_enabled" boolean default false not null,
  constraint "sdr_node_profiles_prf_hz_check" CHECK (((prf_hz >= (0.83)::double precision) AND (prf_hz <= (1.1)::double precision))),
  constraint "sdr_node_profiles_calibration_snapshot_id_fkey" FOREIGN KEY (calibration_snapshot_id) REFERENCES mesh_frozen_snapshots(id),
  constraint "sdr_node_profiles_node_id_fkey" FOREIGN KEY (node_id) REFERENCES mesh_nodes(id),
  constraint "sdr_node_profiles_twin_id_fkey" FOREIGN KEY (twin_id) REFERENCES twin_identity(id),
  constraint "sdr_node_profiles_pkey" PRIMARY KEY (id),
  constraint "sdr_node_profiles_twin_id_node_id_key" UNIQUE (twin_id, node_id)
);

