  constraint "skin_dielectric_readings_epsilon_r_check" CHECK ((epsilon_r > (1)::double precision)),
  constraint "skin_dielectric_readings_gsr_reading_id_fkey" FOREIGN KEY (gsr_reading_id) REFERENCES gsr_readings(id),
  constraint "skin_dielectric_readings_node_id_fkey" FOREIGN KEY (node_id) REFERENCES mesh_nodes(id),
  constraint "skin_dielectric_readings_session_id_fkey" FOREIGN KEY (session_id) REFERENCES edge_gateway_sessions(id),
