  "xrpl_tx_hash" text,
  "accessed_at" timestamp with time zone default now() not null,
  constraint "snapshot_access_log_ephemeral_key_id_fkey" FOREIGN KEY (ephemeral_key_id) REFERENCES snapshot_ephemeral_keys(id),
  constraint "snapshot_access_log_snapshot_id_fkey" FOREIGN KEY (snapshot_id) REFERENCES mesh_frozen_snapshots(id),
  constraint "snapshot_access_log_twin_id_fkey" FOREIGN KEY (twin_id) REFERENCES twin_identity(id),
