  "revoked_at" timestamp with time zone,
  "issued_to" text,
  "sig_count" smallint default 0 not null,
  constraint "ephemeral_key_24hr" CHECK ((expires_at = (issued_at + '24:00:00'::interval))),
  constraint "snapshot_ephemeral_keys_snapshot_id_fkey" FOREIGN KEY (snapshot_id) REFERENCES mesh_frozen_snapshots(id),
  constraint "snapshot_ephemeral_keys_twin_id_fkey" FOREIGN KEY (twin_id) REFERENCES twin_identity(id),
  constraint "snapshot_ephemeral_keys_pkey" PRIMARY KEY (id),
