create table public."spectrum_recordings" (
  "id" uuid default gen_random_uuid() not null,
  "user_id" uuid not null,
  "session_id" uuid,
  "node_id" smallint,
  "frequency_mhz" numeric(14,6) not null,
  "bandwidth_mhz" numeric(10,4) default 10.0 not null,
  "sample_rate_mhz" numeric(10,4) default 10.0 not null,
  "fft_size" integer default 1024 not null,
  "power_dbm" real not null,
  "noise_floor_dbm" real,
  "snr_db" real generated always as (
CASE
    WHEN (noise_floor_dbm IS NOT NULL) THEN (power_dbm - noise_floor_dbm)
    ELSE NULL::real
END) stored,
  "peak_count" integer default 0 not null,
  "iq_data_hash" text,
  "iq_bucket_path" text,
  "spectrum_bins" jsonb,
  "access_tier" text default 'LOW'::text not null,
  "metadata" jsonb default '{}'::jsonb not null,
  "timestamp" timestamp with time zone default now() not null,
  constraint "spectrum_recordings_node_id_fkey" FOREIGN KEY (node_id) REFERENCES mesh_nodes(id),
  constraint "spectrum_recordings_session_id_fkey" FOREIGN KEY (session_id) REFERENCES spectrum_sessions(id) ON DELETE SET NULL,
  constraint "spectrum_recordings_user_id_fkey" FOREIGN KEY (user_id) REFERENCES twin_identity(id) ON DELETE CASCADE,
  constraint "spectrum_recordings_pkey" PRIMARY KEY (id)
);

create table public."spectrum_sessions" (
  "id" uuid default gen_random_uuid() not null,
  "user_id" uuid not null,
  "node_id" smallint,
  "device_type" sdr_device_type default 'hackrf'::sdr_device_type not null,
  "center_freq_mhz" numeric(14,6) not null,
  "sample_rate_mhz" numeric(10,4) default 10.0 not null,
  "gain_db" real default 0.0,
  "started_at" timestamp with time zone default now() not null,
  "ended_at" timestamp with time zone,
  "duration_ms" integer generated always as (
CASE
    WHEN (ended_at IS NOT NULL) THEN ((EXTRACT(epoch FROM (ended_at - started_at)))::integer * 1000)
    ELSE NULL::integer
END) stored,
  "session_hash" text,
  "recording_count" integer default 0 not null,
  "notes" text,
  constraint "session_times" CHECK (((ended_at IS NULL) OR (ended_at >= started_at))),
  constraint "spectrum_sessions_node_id_fkey" FOREIGN KEY (node_id) REFERENCES mesh_nodes(id),
  constraint "spectrum_sessions_user_id_fkey" FOREIGN KEY (user_id) REFERENCES twin_identity(id) ON DELETE CASCADE,
  constraint "spectrum_sessions_pkey" PRIMARY KEY (id)
);

