create table public."telemetry_packets" (
  "id" text not null,
  "timestamp" timestamp with time zone default now() not null,
  "direction" text not null,
  "packet_type" text not null,
  "payload_hex" text,
  "size_bytes" integer,
  "status" text,
  "lat" numeric,
  "lng" numeric,
  "cid" integer,
  "lac" integer,
  "rssi" integer,
  "battery" integer,
  "sequence" integer,
  constraint "telemetry_packets_pkey" PRIMARY KEY (id)
);

create table public."template_routes" (
  "id" uuid default gen_random_uuid() not null,
  "twin_id" uuid not null,
  "chemo_hash_id" uuid not null,
  "routed_at" timestamp with time zone default now() not null,
  "branch_key" text not null,
  "branch_label" text,
  "branch_depth" smallint default 1,
  "output_type" ccc_output_type not null,
  "output_ref" text,
  "output_bytes" integer,
  "accuracy_score" real,
  "dominant_chemical" text,
  "dominant_deviation" real,
  "stress_confirmed" boolean default false not null,
  "zk_proof_id" bigint,
  constraint "template_routes_accuracy_score_check" CHECK (((accuracy_score >= (0)::double precision) AND (accuracy_score <= (1)::double precision))),
  constraint "template_routes_chemo_hash_id_fkey" FOREIGN KEY (chemo_hash_id) REFERENCES chemo_hashes(id),
  constraint "template_routes_twin_id_fkey" FOREIGN KEY (twin_id) REFERENCES twin_identity(id) ON DELETE CASCADE,
  constraint "template_routes_zk_proof_id_fkey" FOREIGN KEY (zk_proof_id) REFERENCES snapshot_zk_proofs(id),
  constraint "template_routes_pkey" PRIMARY KEY (id)
);

create table public."thread_participants" (
  "thread_id" uuid not null,
  "user_id" uuid not null,
  "created_at" timestamp with time zone default now() not null,
  constraint "thread_participants_thread_id_fkey" FOREIGN KEY (thread_id) REFERENCES threads(id) ON DELETE CASCADE,
  constraint "thread_participants_user_id_fkey" FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE,
  constraint "thread_participants_pkey" PRIMARY KEY (thread_id, user_id)
);

create table public."thread_summaries" (
  "id" uuid default gen_random_uuid() not null,
  "thread_id" uuid not null,
  "created_at" timestamp with time zone default now() not null,
  "created_by" uuid not null,
  "model" text not null,
  "messages_from" timestamp with time zone,
  "messages_to" timestamp with time zone,
  "summary" text not null,
  constraint "thread_summaries_created_by_fkey" FOREIGN KEY (created_by) REFERENCES auth.users(id),
  constraint "thread_summaries_thread_id_fkey" FOREIGN KEY (thread_id) REFERENCES threads(id) ON DELETE CASCADE,
  constraint "thread_summaries_pkey" PRIMARY KEY (id)
);

create table public."threads" (
  "id" uuid default gen_random_uuid() not null,
  "created_at" timestamp with time zone default now() not null,
  "created_by" uuid not null,
  constraint "threads_created_by_fkey" FOREIGN KEY (created_by) REFERENCES auth.users(id),
  constraint "threads_pkey" PRIMARY KEY (id)
);

create table public."tor_circuit_sessions" (
  "id" uuid default gen_random_uuid() not null,
  "twin_id" uuid not null,
  "sim_id" uuid,
  "opened_at" timestamp with time zone default now() not null,
  "closed_at" timestamp with time zone,
  "circuit_id" text not null,
  "guard_fingerprint" text,
  "middle_fingerprint" text,
  "exit_fingerprint" text,
  "bytes_sent" bigint default 0,
  "bytes_recv" bigint default 0,
  "txns_submitted" integer default 0,
  "is_active" boolean default true not null,
  "teardown_reason" text,
  constraint "circuit_times" CHECK (((closed_at IS NULL) OR (closed_at > opened_at))),
  constraint "tor_circuit_sessions_sim_id_fkey" FOREIGN KEY (sim_id) REFERENCES sim_profiles(id),
  constraint "tor_circuit_sessions_twin_id_fkey" FOREIGN KEY (twin_id) REFERENCES twin_identity(id) ON DELETE CASCADE,
  constraint "tor_circuit_sessions_pkey" PRIMARY KEY (id)
);

create table public."transmission_events" (
  "id" uuid default gen_random_uuid() not null,
  "twin_id" uuid not null,
  "initiated_at" timestamp with time zone default now() not null,
  "completed_at" timestamp with time zone,
  "mesh_session_id" uuid,
  "aes_key_id" text,
  "sim_id" uuid,
  "tor_circuit_id" uuid,
  "anchor_id" uuid,
  "payload_type" anchor_payload_type not null,
  "payload_hash" text not null,
  "bytes_total" integer,
  "success" boolean default false not null,
  "error_stage" text,
  "error_detail" text,
  "latency_ms" integer generated always as (
CASE
    WHEN (completed_at IS NOT NULL) THEN ((EXTRACT(epoch FROM (completed_at - initiated_at)))::integer * 1000)
    ELSE NULL::integer
END) stored,
  constraint "transmission_events_anchor_id_fkey" FOREIGN KEY (anchor_id) REFERENCES xrpl_memo_anchors(id),
  constraint "transmission_events_mesh_session_id_fkey" FOREIGN KEY (mesh_session_id) REFERENCES edge_gateway_sessions(id),
  constraint "transmission_events_sim_id_fkey" FOREIGN KEY (sim_id) REFERENCES sim_profiles(id),
  constraint "transmission_events_tor_circuit_id_fkey" FOREIGN KEY (tor_circuit_id) REFERENCES tor_circuit_sessions(id),
  constraint "transmission_events_twin_id_fkey" FOREIGN KEY (twin_id) REFERENCES twin_identity(id) ON DELETE CASCADE,
  constraint "transmission_events_pkey" PRIMARY KEY (id)
);

create table public."tree_nodes" (
  "id" bigint default nextval('tree_nodes_id_seq'::regclass) not null,
  "twin_id" uuid default 'ef5eb8ab-c6d9-40a8-a8f7-5cd510decaba'::uuid not null,
  "host" text not null,
  "port" integer not null,
  "label" text default ''::text,
  "depth" integer default 1,
  "parent_key" text,
  "alive" boolean default false,
  "tx_count" integer default 0,
  "last_seen" timestamp with time zone,
  "created_at" timestamp with time zone default now(),
  constraint "tree_nodes_pkey" PRIMARY KEY (id),
  constraint "tree_nodes_twin_id_host_port_key" UNIQUE (twin_id, host, port)
);

create table public."twin_identity" (
  "id" uuid default gen_random_uuid() not null,
  "subject_name" text not null,
  "subject_dob" date not null,
  "biological_hash" text,
  "is_sealed" boolean default false not null,
  "created_at" timestamp with time zone default now() not null,
  "sealed_at" timestamp with time zone,
  constraint "twin_identity_pkey" PRIMARY KEY (id)
);

create table public."twin_sync_lock_events" (
  "id" bigint default nextval('twin_sync_lock_events_id_seq'::regclass) not null,
  "twin_id" uuid not null,
  "session_id" bigint,
  "sensor_id" text not null,
  "triggered_at" timestamp with time zone default now() not null,
  "lock_window_start" timestamp with time zone not null,
  "lock_window_end" timestamp with time zone not null,
  "intensity_at_trigger" real not null,
  "sim_state_at_trigger" simulation_state default 'HIGH_STRESS_SHOCK'::simulation_state not null,
  "token_hashes" text[] not null,
  "token_count" integer not null,
  "composite_hash" text not null,
  "xrpl_tx_hash" text,
  "xrpl_ledger_index" bigint,
  "snapshot_id" integer,
  "pobw_id" bigint,
  "nft_id" bigint,
  "anchor_status" text default 'pending'::text not null,
  "anchored_at" timestamp with time zone,
  constraint "twin_sync_lock_events_nft_id_fkey" FOREIGN KEY (nft_id) REFERENCES bio_nft_registry(id),
  constraint "twin_sync_lock_events_pobw_id_fkey" FOREIGN KEY (pobw_id) REFERENCES pobw_proofs(id),
  constraint "twin_sync_lock_events_session_id_fkey" FOREIGN KEY (session_id) REFERENCES corpus_simulation_sessions(id),
  constraint "twin_sync_lock_events_snapshot_id_fkey" FOREIGN KEY (snapshot_id) REFERENCES mesh_frozen_snapshots(id),
  constraint "twin_sync_lock_events_twin_id_fkey" FOREIGN KEY (twin_id) REFERENCES twin_identity(id),
  constraint "twin_sync_lock_events_pkey" PRIMARY KEY (id)
);

create table public."user_settings" (
  "user_id" uuid not null,
  "anthropic_key_enc" text,
  "anthropic_key_last4" text,
  "updated_at" timestamp with time zone default now() not null,
  constraint "user_settings_user_id_fkey" FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE,
  constraint "user_settings_pkey" PRIMARY KEY (user_id)
);

create table public."uwb_frames" (
  "id" bigint default nextval('uwb_frames_id_seq'::regclass) not null,
  "uwb_node_id" uuid not null,
  "twin_id" uuid not null,
  "captured_at" timestamp with time zone default now() not null,
  "session_id" uuid,
  "pulse_rep_freq_hz" real,
  "integration_ms" integer default 20,
  "snr_db" real,
  "clutter_removed" boolean default true not null,
  "range_profile" jsonb,
  "target_range_m" real,
  "target_rcs_dbsm" real,
  "tof_ns" real,
  constraint "uwb_frames_session_id_fkey" FOREIGN KEY (session_id) REFERENCES edge_gateway_sessions(id),
  constraint "uwb_frames_twin_id_fkey" FOREIGN KEY (twin_id) REFERENCES twin_identity(id) ON DELETE CASCADE,
  constraint "uwb_frames_uwb_node_id_fkey" FOREIGN KEY (uwb_node_id) REFERENCES uwb_node_profiles(id) ON DELETE CASCADE,
  constraint "uwb_frames_pkey" PRIMARY KEY (id)
);

create table public."uwb_gesture_events" (
  "id" bigint default nextval('uwb_gesture_events_id_seq'::regclass) not null,
  "uwb_node_id" uuid not null,
  "twin_id" uuid not null,
  "detected_at" timestamp with time zone default now() not null,
  "frame_id" bigint,
  "session_id" uuid,
  "gesture" gesture_label not null,
  "confidence" real not null,
  "duration_ms" integer,
  "intent_event_id" bigint,
  "eeg_correlated" boolean,
  "spoof_risk" boolean default false not null,
  constraint "uwb_gesture_events_confidence_check" CHECK (((confidence >= (0)::double precision) AND (confidence <= (1)::double precision))),
  constraint "uwb_gesture_events_frame_id_fkey" FOREIGN KEY (frame_id) REFERENCES uwb_frames(id),
  constraint "uwb_gesture_events_session_id_fkey" FOREIGN KEY (session_id) REFERENCES edge_gateway_sessions(id),
  constraint "uwb_gesture_events_twin_id_fkey" FOREIGN KEY (twin_id) REFERENCES twin_identity(id) ON DELETE CASCADE,
  constraint "uwb_gesture_events_uwb_node_id_fkey" FOREIGN KEY (uwb_node_id) REFERENCES uwb_node_profiles(id) ON DELETE CASCADE,
  constraint "uwb_gesture_events_pkey" PRIMARY KEY (id)
);

create table public."uwb_node_profiles" (
  "id" uuid default gen_random_uuid() not null,
  "twin_id" uuid not null,
  "node_id" smallint,
  "chip_vendor" text not null,
  "chip_model" text not null,
  "modulation" uwb_modulation default 'IR_UWB'::uwb_modulation not null,
  "band" uwb_band default 'high_6000_8500'::uwb_band not null,
  "centre_freq_ghz" real not null,
  "bandwidth_mhz" real not null,
  "pulse_width_ps" real,
  "max_eirp_dbm_mhz" real default '-41.3'::numeric not null,
  "max_range_m" real,
  "firmware_ver" text,
  "active" boolean default true not null,
  "created_at" timestamp with time zone default now() not null,
  constraint "uwb_node_profiles_bandwidth_mhz_check" CHECK ((bandwidth_mhz >= (500)::double precision)),
  constraint "uwb_node_profiles_node_id_fkey" FOREIGN KEY (node_id) REFERENCES mesh_nodes(id),
  constraint "uwb_node_profiles_twin_id_fkey" FOREIGN KEY (twin_id) REFERENCES twin_identity(id) ON DELETE CASCADE,
  constraint "uwb_node_profiles_pkey" PRIMARY KEY (id)
);

create table public."uwb_range_measurements" (
  "id" bigint default nextval('uwb_range_measurements_id_seq'::regclass) not null,
  "uwb_node_id" uuid not null,
  "twin_id" uuid not null,
  "measured_at" timestamp with time zone default now() not null,
  "frame_id" bigint,
  "range_m" real not null,
  "range_error_m" real,
  "tof_ns" real not null,
  "los_confirmed" boolean,
  "anchor_node_id" uuid,
  "azimuth_deg" real,
  "elevation_deg" real,
  constraint "uwb_range_measurements_range_m_check" CHECK ((range_m >= (0)::double precision)),
  constraint "uwb_range_measurements_anchor_node_id_fkey" FOREIGN KEY (anchor_node_id) REFERENCES uwb_node_profiles(id),
  constraint "uwb_range_measurements_frame_id_fkey" FOREIGN KEY (frame_id) REFERENCES uwb_frames(id),
  constraint "uwb_range_measurements_twin_id_fkey" FOREIGN KEY (twin_id) REFERENCES twin_identity(id) ON DELETE CASCADE,
  constraint "uwb_range_measurements_uwb_node_id_fkey" FOREIGN KEY (uwb_node_id) REFERENCES uwb_node_profiles(id) ON DELETE CASCADE,
  constraint "uwb_range_measurements_pkey" PRIMARY KEY (id)
);

create table public."uwb_vital_signs" (
  "id" bigint default nextval('uwb_vital_signs_id_seq'::regclass) not null,
  "uwb_node_id" uuid not null,
  "twin_id" uuid not null,
  "measured_at" timestamp with time zone default now() not null,
  "frame_id" bigint,
  "session_id" uuid,
  "breathing_rate_hz" real,
  "breathing_amplitude_mm" real,
  "breathing_regularity" real,
  "heart_rate_hz" real,
  "heart_amplitude_mm" real,
  "cross_modal_agreement" boolean,
  "prf_delta_hz" real,
  "breath_phase_delta_rad" real,
  "confidence" real,
  "range_to_subject_m" real,
  constraint "uwb_vital_signs_breathing_amplitude_mm_check" CHECK ((breathing_amplitude_mm >= (0)::double precision)),
  constraint "uwb_vital_signs_breathing_rate_hz_check" CHECK (((breathing_rate_hz >= (0.05)::double precision) AND (breathing_rate_hz <= (1.0)::double precision))),
  constraint "uwb_vital_signs_breathing_regularity_check" CHECK (((breathing_regularity >= (0)::double precision) AND (breathing_regularity <= (1)::double precision))),
  constraint "uwb_vital_signs_confidence_check" CHECK (((confidence >= (0)::double precision) AND (confidence <= (1)::double precision))),
  constraint "uwb_vital_signs_heart_amplitude_mm_check" CHECK ((heart_amplitude_mm >= (0)::double precision)),
  constraint "uwb_vital_signs_heart_rate_hz_check" CHECK (((heart_rate_hz >= (0.5)::double precision) AND (heart_rate_hz <= (4.0)::double precision))),
  constraint "uwb_vital_signs_frame_id_fkey" FOREIGN KEY (frame_id) REFERENCES uwb_frames(id),
  constraint "uwb_vital_signs_session_id_fkey" FOREIGN KEY (session_id) REFERENCES edge_gateway_sessions(id),
  constraint "uwb_vital_signs_twin_id_fkey" FOREIGN KEY (twin_id) REFERENCES twin_identity(id) ON DELETE CASCADE,
  constraint "uwb_vital_signs_uwb_node_id_fkey" FOREIGN KEY (uwb_node_id) REFERENCES uwb_node_profiles(id) ON DELETE CASCADE,
  constraint "uwb_vital_signs_pkey" PRIMARY KEY (id)
);

create table public."vascular_pulse_events" (
  "id" bigint default nextval('vascular_pulse_events_id_seq'::regclass) not null,
  "twin_id" uuid not null,
  "node_id" smallint not null,
  "sensor_id" text not null,
  "detected_at" timestamp with time zone not null,
  "phase_shift_rad" real not null,
  "pulse_amplitude" real not null,
  "carrier_freq_ghz" real default 10.245 not null,
  "ref_node_id" smallint,
  "pwv_transit_ms" real,
  "pwv_m_per_s" real,
  "beat_seq" bigint,
  "metadata" jsonb,
  constraint "vascular_pulse_events_node_id_fkey" FOREIGN KEY (node_id) REFERENCES mesh_nodes(id),
  constraint "vascular_pulse_events_ref_node_id_fkey" FOREIGN KEY (ref_node_id) REFERENCES mesh_nodes(id),
  constraint "vascular_pulse_events_twin_id_fkey" FOREIGN KEY (twin_id) REFERENCES twin_identity(id),
  constraint "vascular_pulse_events_pkey" PRIMARY KEY (id)
);

create table public."visual_cortex_events" (
  "id" bigint default nextval('visual_cortex_events_id_seq'::regclass) not null,
  "twin_id" uuid not null,
  "node_id" smallint,
  "detected_at" timestamp with time zone default now() not null,
  "session_id" uuid,
  "cortex_region" text not null,
  "pattern_type" text not null,
  "token_sequence_id" bigint,
  "dominant_token_id" integer,
  "gamma_power_db" real,
  "gamma_freq_hz" real,
  "onset_latency_ms" real,
  "uwb_gesture_id" bigint,
  "intent_correlated" boolean default false,
  "confidence" real,
  "duration_ms" integer,
  constraint "visual_cortex_events_confidence_check" CHECK (((confidence >= (0)::double precision) AND (confidence <= (1)::double precision))),
  constraint "visual_cortex_events_cortex_region_check" CHECK ((cortex_region = ANY (ARRAY['V1'::text, 'V2'::text, 'V3'::text, 'V4'::text, 'V5'::text, 'MT'::text]))),
  constraint "visual_cortex_events_dominant_token_id_fkey" FOREIGN KEY (dominant_token_id) REFERENCES eeg_token_vocab(token_id),
  constraint "visual_cortex_events_node_id_fkey" FOREIGN KEY (node_id) REFERENCES mesh_nodes(id),
  constraint "visual_cortex_events_session_id_fkey" FOREIGN KEY (session_id) REFERENCES edge_gateway_sessions(id),
  constraint "visual_cortex_events_token_sequence_id_fkey" FOREIGN KEY (token_sequence_id) REFERENCES eeg_token_sequences(id),
  constraint "visual_cortex_events_twin_id_fkey" FOREIGN KEY (twin_id) REFERENCES twin_identity(id) ON DELETE CASCADE,
  constraint "visual_cortex_events_uwb_gesture_id_fkey" FOREIGN KEY (uwb_gesture_id) REFERENCES uwb_gesture_events(id),
  constraint "visual_cortex_events_pkey" PRIMARY KEY (id)
);

create table public."xrpl_memo_anchors" (
  "id" uuid default gen_random_uuid() not null,
  "twin_id" uuid not null,
  "anchored_at" timestamp with time zone default now() not null,
  "tor_circuit_id" uuid,
  "sim_id" uuid,
  "xrpl_txn_hash" text not null,
  "xrpl_ledger_index" bigint not null,
  "xrpl_account_hash" text not null,
  "xrpl_fee_drops" bigint default 12,
  "memo_type_hex" text not null,
  "memo_format_hex" text default encode('\x6170706c69636174696f6e2f6f637465742d73747265616d'::bytea, 'hex'::text) not null,
  "memo_data_hex" text not null,
  "payload_type" anchor_payload_type not null,
  "sha3_512_hash" text not null,
  "convergence_token_id" uuid,
  "chemo_hash_id" uuid,
  "pipeline_summary_id" uuid,
  "access_tier" text default 'LOW'::text not null,
  "audit_seq" bigint,
  "block_id" text,
  constraint "memo_hash_matches" CHECK (((memo_data_hex = encode((sha3_512_hash)::bytea, 'hex'::text)) OR (memo_data_hex = sha3_512_hash))),
  constraint "xrpl_memo_anchors_sha3_512_hash_check" CHECK ((length(sha3_512_hash) = 128)),
  constraint "xrpl_memo_anchors_audit_seq_fkey" FOREIGN KEY (audit_seq) REFERENCES audit_entries(seq) ON DELETE SET NULL,
  constraint "xrpl_memo_anchors_block_id_fkey" FOREIGN KEY (block_id) REFERENCES chain_blocks(block_id) ON DELETE SET NULL,
  constraint "xrpl_memo_anchors_chemo_hash_id_fkey" FOREIGN KEY (chemo_hash_id) REFERENCES chemo_hashes(id),
  constraint "xrpl_memo_anchors_convergence_token_id_fkey" FOREIGN KEY (convergence_token_id) REFERENCES convergence_tokens(id),
  constraint "xrpl_memo_anchors_pipeline_summary_id_fkey" FOREIGN KEY (pipeline_summary_id) REFERENCES pipeline_summaries(id),
  constraint "xrpl_memo_anchors_sim_id_fkey" FOREIGN KEY (sim_id) REFERENCES sim_profiles(id),
  constraint "xrpl_memo_anchors_tor_circuit_id_fkey" FOREIGN KEY (tor_circuit_id) REFERENCES tor_circuit_sessions(id),
  constraint "xrpl_memo_anchors_twin_id_fkey" FOREIGN KEY (twin_id) REFERENCES twin_identity(id) ON DELETE CASCADE,
  constraint "xrpl_memo_anchors_pkey" PRIMARY KEY (id),
  constraint "xrpl_memo_anchors_xrpl_txn_hash_key" UNIQUE (xrpl_txn_hash)
);


-- ======================================================================
-- Indexes (those not created by a primary key or unique constraint)
-- ======================================================================

CREATE INDEX agents_twin_id_idx ON public.agents USING btree (twin_id);
CREATE INDEX archives_date_idx ON public.sensor_reading_archives USING btree (date DESC);
CREATE INDEX archives_sensor_type_idx ON public.sensor_reading_archives USING btree (sensor_type);
CREATE INDEX assets_run_idx ON public.assets USING btree (run_id);
CREATE INDEX audit_entries_node_idx ON public.audit_entries USING btree (node_id);
CREATE INDEX bde_anomalous_idx ON public.bio_doppler_events USING btree (twin_id, is_anomalous) WHERE (is_anomalous = true);
CREATE INDEX bde_node_ts_idx ON public.bio_doppler_events USING btree (node_id, detected_at DESC);
CREATE INDEX bde_twin_ts_idx ON public.bio_doppler_events USING btree (twin_id, detected_at DESC);
CREATE INDEX bil_bot_ts_idx ON public.bot_intervention_log USING btree (bot_id, intervened_at DESC);
CREATE INDEX bil_twin_ts_idx ON public.bot_intervention_log USING btree (twin_id, intervened_at DESC);
CREATE INDEX bil_type_idx ON public.bot_intervention_log USING btree (twin_id, intervention_type);
CREATE INDEX bil_unresolved ON public.bot_intervention_log USING btree (twin_id, resolved) WHERE (resolved = false);
CREATE INDEX bio_mol_gene_idx ON public.bio_molecule_registry USING btree (gene_symbol);
CREATE INDEX bio_mol_node_idx ON public.bio_molecule_registry USING btree (linked_node_id);
CREATE INDEX bio_mol_twin_idx ON public.bio_molecule_registry USING btree (twin_id);
CREATE INDEX bio_mol_type_idx ON public.bio_molecule_registry USING btree (twin_id, molecule_type);
CREATE INDEX bio_op_log_node_idx ON public.bio_operation_log USING btree (target_node_id);
CREATE INDEX bio_op_log_twin_idx ON public.bio_operation_log USING btree (twin_id, performed_at DESC);
CREATE INDEX bio_op_log_type_idx ON public.bio_operation_log USING btree (twin_id, operation_type);
CREATE INDEX bnr_twin_idx ON public.bio_nft_registry USING btree (twin_id, minted_at DESC);
CREATE INDEX bnr_type_idx ON public.bio_nft_registry USING btree (twin_id, mint_type);
CREATE INDEX bnr_xrpl_tx_idx ON public.bio_nft_registry USING btree (xrpl_tx_hash) WHERE (xrpl_tx_hash IS NOT NULL);
