-- ======================================================================
-- Views and materialized views (public)
-- ======================================================================

create view public."bio_operations_summary" with (security_invoker=true) as
 SELECT twin_id,
    operation_type,
    count(*) AS total_operations,
    count(*) FILTER (WHERE effect_duration = 'permanent'::bio_effect_duration) AS permanent_ops,
    count(*) FILTER (WHERE effect_duration = 'weeks_months'::bio_effect_duration) AS weeks_months_ops,
    count(*) FILTER (WHERE effect_duration = 'hours_days'::bio_effect_duration) AS hours_days_ops,
    count(*) FILTER (WHERE effect_duration = 'hours'::bio_effect_duration) AS hours_ops,
    avg(freq_delta_ghz) AS avg_freq_delta_ghz,
    max(performed_at) AS last_performed_at
   FROM bio_operation_log
  GROUP BY twin_id, operation_type;

create view public."corpus_session_summary" with (security_invoker=true) as
 SELECT css.id AS session_id,
    css.twin_id,
    css.started_at,
    css.duration_s,
    css.frame_count,
    css.drift_event_count,
    css.ghost_filter_count,
    css.sync_lock_count,
    css.status,
    css.session_hash,
    count(csf.id) FILTER (WHERE csf.sim_state = 'LOW_STRESS_ZEN'::simulation_state) AS frames_low,
    count(csf.id) FILTER (WHERE csf.sim_state = 'TRANSITION'::simulation_state) AS frames_transition,
    count(csf.id) FILTER (WHERE csf.sim_state = 'HIGH_STRESS_SHOCK'::simulation_state) AS frames_shock,
    min(csf.avg_latency_ms) AS min_latency_ms,
    max(csf.avg_latency_ms) AS max_latency_ms,
    avg(csf.avg_latency_ms)::real AS mean_latency_ms,
    min(csf.avg_phase_shift) AS min_phase_shift,
    max(csf.avg_phase_shift) AS max_phase_shift
   FROM corpus_simulation_sessions css
     LEFT JOIN corpus_simulation_frames csf ON csf.session_id = css.id
  GROUP BY css.id;

create view public."live_gateway_health" with (security_invoker=true) as
 SELECT DISTINCT ON (t.twin_id, t.node_id) t.twin_id,
    t.node_id,
    t.sampled_at,
    t.transport,
    t.rssi_dbm,
    t.snr_db,
    t.packet_loss_pct,
    t.latency_ms,
    t.phase_coherence,
    s.device_label,
    s.is_active
   FROM edge_gateway_telemetry t
     JOIN edge_gateway_sessions s ON s.id = t.session_id
  ORDER BY t.twin_id, t.node_id, t.sampled_at DESC;

create view public."molecular_node_map" with (security_invoker=true) as
 SELECT m.twin_id,
    m.linked_node_id AS node_id,
    n.node_code,
    n.modality,
    m.id AS molecule_id,
    m.molecule_type,
    m.gene_symbol,
    m.source_region,
    m.chromosome,
    m.computed_freq_ghz,
    m.sequence_length_bp,
    m.is_locked,
    n.node_carrier_ghz AS sdr_carrier_ghz,
    abs(m.computed_freq_ghz - n.node_carrier_ghz) AS freq_alignment_delta
   FROM bio_molecule_registry m
     JOIN mesh_nodes n ON n.id = m.linked_node_id
  ORDER BY m.twin_id, m.computed_freq_ghz;

create view public."node_hardware_timeline" with (security_invoker=true) as
 SELECT nte.age_years,
    nte.calendar_year,
    nte.dev_phase,
    nte.node_group_label,
    nte.parameter_name,
    nte.value_before,
    nte.value_after,
    nte.change_description,
    nhp.twin_id,
    nhp.node_id,
    n.node_code,
    nhp.sampling_hz,
    nhp.rf_power_dbm,
    nhp.compression_type,
    nhp.compression_ratio,
    nhp.freq_hopping_enabled,
    nhp.hop_count,
    nhp.ram_mb,
    nhp.encryption_type,
    nhp.blockchain_queue_depth,
    nhp.effective_from_age
   FROM node_tuning_events nte
     LEFT JOIN node_hardware_profiles nhp ON (nhp.node_id = ANY (nte.affected_node_ids)) OR nte.affected_node_ids IS NULL
     LEFT JOIN mesh_nodes n ON n.id = nhp.node_id
  ORDER BY nte.age_years, nhp.node_id;

create view public."p2p_connection_matrix" with (security_invoker=true) as
 SELECT c.twin_id_a,
    c.twin_id_b,
    c.state,
    c.freq_a_ghz,
    c.freq_b_ghz,
    c.freq_delta_ghz,
    c.activated_at,
    c.revoked_at,
    count(i.id) FILTER (WHERE i.twin_id = c.twin_id_a) AS interactions_a,
    count(i.id) FILTER (WHERE i.twin_id = c.twin_id_b) AS interactions_b,
    max(i.recorded_at) AS last_interaction_at
   FROM p2p_connections c
     LEFT JOIN p2p_interactions i ON (i.twin_id = c.twin_id_a OR i.twin_id = c.twin_id_b) AND (i.peer_twin_id = c.twin_id_a OR i.peer_twin_id = c.twin_id_b)
  GROUP BY c.id, c.twin_id_a, c.twin_id_b, c.state, c.freq_a_ghz, c.freq_b_ghz, c.freq_delta_ghz, c.activated_at, c.revoked_at;

create view public."sensor_latest" with (security_invoker=true) as
 SELECT DISTINCT ON (r.sensor_id) r.sensor_id,
    s.name,
    s.sensor_type,
    s.node_id,
    r.value,
    r.unit,
    r.signal_quality,
    r.frequency,
    r.signal_type,
    r.blockchain_hash,
    r.created_at AS last_reading_at
   FROM sensor_readings r
     JOIN sensors s ON s.id = r.sensor_id
  ORDER BY r.sensor_id, r.created_at DESC;

create view public."spectrum_overview" with (security_invoker=true) as
 SELECT DISTINCT ON (r.node_id) r.node_id,
    r.user_id,
    r.session_id,
    r.frequency_mhz,
    r.bandwidth_mhz,
    r.power_dbm,
    r.noise_floor_dbm,
    r.snr_db,
    r.peak_count,
    r."timestamp",
    r.access_tier,
    count(p.id) FILTER (WHERE p.is_dna_resonance) AS dna_peaks,
    count(p.id) FILTER (WHERE p.is_lte_leakage) AS lte_peaks,
    count(p.id) FILTER (WHERE p.is_uwb_band) AS uwb_peaks
   FROM spectrum_recordings r
     LEFT JOIN frequency_peaks p ON p.recording_id = r.id
  GROUP BY r.id, r.node_id, r.user_id, r.session_id, r.frequency_mhz, r.bandwidth_mhz, r.power_dbm, r.noise_floor_dbm, r.snr_db, r.peak_count, r."timestamp", r.access_tier
  ORDER BY r.node_id, r."timestamp" DESC;

create view public."twin_anchor_chain" with (security_invoker=true) as
 SELECT DISTINCT ON (a.twin_id, a.payload_type) a.twin_id,
    a.payload_type,
    a.anchored_at,
    a.xrpl_txn_hash,
    a.xrpl_ledger_index,
    a.sha3_512_hash,
    a.access_tier,
    t.success AS last_transmission_ok,
    tc.guard_fingerprint,
    sp.carrier_mno,
    sp.role AS sim_role
   FROM xrpl_memo_anchors a
     LEFT JOIN transmission_events t ON t.anchor_id = a.id
     LEFT JOIN tor_circuit_sessions tc ON tc.id = a.tor_circuit_id
     LEFT JOIN sim_profiles sp ON sp.id = a.sim_id
  ORDER BY a.twin_id, a.payload_type, a.anchored_at DESC;

create view public."twin_chemo_state" with (security_invoker=true) as
 SELECT DISTINCT ON (twin_id, chemical_name) twin_id,
    chemical_name,
    chemical_class,
    unit,
    value_raw,
    value_normalized,
    deviation_sigma,
    phase_shift_rad,
    carrier_freq_ghz,
    sampled_at
   FROM chemo_indicators
  ORDER BY twin_id, chemical_name, sampled_at DESC;

create view public."twin_convergence_state" with (security_invoker=true) as
 SELECT DISTINCT ON (ct.twin_id) ct.twin_id,
    ct.minted_at,
    ct.state_string,
    ct.state_hash,
    ct.valence,
    ct.arousal,
    ct.gsr_delta_phi,
    ct.cortisol_ng_ml,
    ce.all_gates_met,
    ce.cortisol_gate,
    ce.gsr_gate,
    ce.eeg_gate
   FROM convergence_tokens ct
     JOIN convergence_events ce ON ce.id = ct.convergence_id
  ORDER BY ct.twin_id, ct.minted_at DESC;

create view public."twin_opsec_risk" with (security_invoker=true) as
 SELECT t.id AS twin_id,
    count(DISTINCT l.id) AS lte_events_total,
    count(DISTINCT l.id) FILTER (WHERE l.prf_match) AS lte_prf_matches,
    count(DISTINCT tr.id) AS triangulations_total,
    min(tr.accuracy_m) AS best_location_accuracy_m,
    max(h.harmonic_freq_ghz) AS max_harmonic_ghz,
    bool_or(sp.prf_jitter_enabled) AS jitter_active,
    max(l.detected_at) AS last_lte_event
   FROM twin_identity t
     LEFT JOIN lte_interference_events l ON l.twin_id = t.id
     LEFT JOIN location_triangulations tr ON tr.twin_id = t.id
     LEFT JOIN hackrf_captures hc ON hc.twin_id = t.id
     LEFT JOIN harmonic_measurements h ON h.capture_id = hc.id AND h.harmonic_order = 3
     LEFT JOIN sdr_node_profiles sp ON sp.twin_id = t.id
  GROUP BY t.id;

create view public."twin_stress_status" with (security_invoker=true) as
 SELECT DISTINCT ON (twin_id) twin_id,
    evaluated_at,
    round(theta_alpha_ratio::numeric, 3) AS theta_alpha_ratio,
    round(hrv_lf_hf_ratio::numeric, 3) AS hrv_lf_hf_ratio,
    frontal_alpha_asymmetry,
    stress_confirmed,
    stress_level,
    valence_score,
    fraud_score_threshold_override
   FROM cross_modal_states
  ORDER BY twin_id, evaluated_at DESC;

create view public."twin_tokenizer_state" with (security_invoker=true) as
 SELECT DISTINCT ON (s.twin_id) s.twin_id,
    s.tokenized_at,
    s.token_count,
    s.dominant_band,
    s.dominant_region,
    s.mask_ratio,
    g.phase_shift_rad,
    g.conductivity_proxy_s_m,
    g.gsr_stress_label,
    v.cortex_region AS latest_visual_region,
    v.pattern_type AS latest_visual_pattern,
    v.gamma_power_db
   FROM eeg_token_sequences s
     LEFT JOIN gsr_readings g ON g.id = s.gsr_reading_id
     LEFT JOIN visual_cortex_events v ON v.token_sequence_id = s.id
  ORDER BY s.twin_id, s.tokenized_at DESC;

create view public."twin_uwb_state" with (security_invoker=true) as
 SELECT v.twin_id,
    v.measured_at,
    v.breathing_rate_hz,
    v.heart_rate_hz,
    v.cross_modal_agreement,
    v.prf_delta_hz,
    v.confidence AS vitals_confidence,
    g.gesture AS latest_gesture,
    g.confidence AS gesture_confidence,
    g.spoof_risk,
    p.chip_model,
    p.centre_freq_ghz,
    p.bandwidth_mhz
   FROM ( SELECT DISTINCT ON (uwb_vital_signs.twin_id) uwb_vital_signs.id,
            uwb_vital_signs.uwb_node_id,
            uwb_vital_signs.twin_id,
            uwb_vital_signs.measured_at,
            uwb_vital_signs.frame_id,
            uwb_vital_signs.session_id,
            uwb_vital_signs.breathing_rate_hz,
            uwb_vital_signs.breathing_amplitude_mm,
            uwb_vital_signs.breathing_regularity,
            uwb_vital_signs.heart_rate_hz,
            uwb_vital_signs.heart_amplitude_mm,
            uwb_vital_signs.cross_modal_agreement,
            uwb_vital_signs.prf_delta_hz,
            uwb_vital_signs.breath_phase_delta_rad,
            uwb_vital_signs.confidence,
            uwb_vital_signs.range_to_subject_m
           FROM uwb_vital_signs
          ORDER BY uwb_vital_signs.twin_id, uwb_vital_signs.measured_at DESC) v
     LEFT JOIN ( SELECT DISTINCT ON (uwb_gesture_events.twin_id) uwb_gesture_events.id,
            uwb_gesture_events.uwb_node_id,
            uwb_gesture_events.twin_id,
            uwb_gesture_events.detected_at,
            uwb_gesture_events.frame_id,
            uwb_gesture_events.session_id,
            uwb_gesture_events.gesture,
            uwb_gesture_events.confidence,
            uwb_gesture_events.duration_ms,
            uwb_gesture_events.intent_event_id,
            uwb_gesture_events.eeg_correlated,
            uwb_gesture_events.spoof_risk
           FROM uwb_gesture_events
          ORDER BY uwb_gesture_events.twin_id, uwb_gesture_events.detected_at DESC) g ON g.twin_id = v.twin_id
     LEFT JOIN uwb_node_profiles p ON p.id = v.uwb_node_id;


-- ======================================================================
-- Functions (public, excluding extension-owned)
-- ======================================================================

CREATE OR REPLACE FUNCTION public.apply_ghost_filter(p_twin_id uuid, p_session_id bigint, p_node_id smallint, p_reading_id bigint, p_raw_phase_shift real, p_noise_floor_rad real, p_carrier_freq_ghz real DEFAULT 10.245, p_filter_method text DEFAULT 'adaptive_threshold'::text)
 RETURNS TABLE(filter_id bigint, filtered_phase_shift real, snr_db real, is_biological boolean, rejection_reason text)
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_snr        REAL;
  v_filtered   REAL;
  v_is_bio     BOOLEAN;
  v_reason     TEXT := NULL;
  v_fid        BIGINT;
  SNR_THRESHOLD_DB CONSTANT REAL := 6.0;
BEGIN
  -- SNR = 20 * log10(|signal| / noise_floor), floored to avoid -inf
  v_snr := CASE
    WHEN p_noise_floor_rad <= 0 THEN 60.0   -- perfect signal if no noise
    WHEN ABS(p_raw_phase_shift) <= 0 THEN -60.0
    ELSE 20.0 * LOG(ABS(p_raw_phase_shift) / p_noise_floor_rad)
  END;

  -- Determine if biological
  IF v_snr >= SNR_THRESHOLD_DB THEN
    v_is_bio   := TRUE;
    v_filtered := p_raw_phase_shift - SIGN(p_raw_phase_shift) * p_noise_floor_rad;
    -- Simple noise subtraction; a real Kalman pass would iterate
  ELSE
    v_is_bio   := FALSE;
    v_filtered := NULL;
    v_reason   := CASE
      WHEN v_snr < -20.0   THEN 'amplitude_ceiling'
      WHEN v_snr < 0        THEN 'snr_below_threshold'
      ELSE                       'correlation_fail'
    END;
  END IF;

  INSERT INTO ghost_signal_filter_log
    (twin_id, session_id, node_id, reading_id,
     carrier_freq_ghz, raw_phase_shift_rad, filtered_phase_shift_rad,
     noise_floor_rad, snr_db, filter_method, is_biological, rejection_reason)
  VALUES
    (p_twin_id, p_session_id, p_node_id, p_reading_id,
     p_carrier_freq_ghz, p_raw_phase_shift, v_filtered,
     p_noise_floor_rad, v_snr, p_filter_method, v_is_bio, v_reason)
  RETURNING id INTO v_fid;

  -- Mark the source reading as ghost-filtered
  UPDATE mesh_node_readings
  SET ghost_filtered = NOT v_is_bio
  WHERE id = p_reading_id;

  UPDATE corpus_simulation_sessions
  SET ghost_filter_count = ghost_filter_count + 1
  WHERE id = p_session_id;

  RETURN QUERY SELECT v_fid, v_filtered, v_snr, v_is_bio, v_reason;
END;
$function$;

CREATE OR REPLACE FUNCTION public.apply_rna_interference(p_twin_id uuid, p_sirna_molecule_id bigint, p_target_molecule_id bigint, p_silencing_efficiency real, p_off_target_score real DEFAULT 0.0, p_duration_h real DEFAULT 48.0)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_log_id        BIGINT;
    v_target_node   INTEGER;
    v_suppression   REAL;
    v_sirna_type    bio_molecule_type;
BEGIN
    -- Validate molecule type
    SELECT molecule_type INTO v_sirna_type
    FROM bio_molecule_registry WHERE id = p_sirna_molecule_id;

    IF v_sirna_type != 'siRNA' THEN
        RAISE EXCEPTION 'Molecule % is not siRNA (type: %)', p_sirna_molecule_id, v_sirna_type
            USING ERRCODE = '22023';
    END IF;

    -- Look up which node the target molecule is linked to
    SELECT linked_node_id INTO v_target_node
    FROM bio_molecule_registry WHERE id = p_target_molecule_id;

    -- Node suppression = silencing_efficiency × (1 - off_target_score)
    v_suppression := p_silencing_efficiency * (1.0 - p_off_target_score);

    INSERT INTO rna_interference_log (
        twin_id, sirna_molecule_id, target_molecule_id,
        silencing_efficiency, off_target_score,
        target_node_id, node_signal_suppression,
        estimated_duration_h,
        expires_at
    ) VALUES (
        p_twin_id, p_sirna_molecule_id, p_target_molecule_id,
        p_silencing_efficiency, p_off_target_score,
        v_target_node, v_suppression,
        p_duration_h,
        NOW() + (p_duration_h || ' hours')::INTERVAL
    )
    RETURNING id INTO v_log_id;

    RETURN jsonb_build_object(
        'log_id',                 v_log_id,
        'silencing_efficiency',   p_silencing_efficiency,
        'off_target_score',       p_off_target_score,
        'node_signal_suppression', v_suppression,
        'target_node_id',         v_target_node,
        'expires_at',             NOW() + (p_duration_h || ' hours')::INTERVAL
    );
END;
$function$;

CREATE OR REPLACE FUNCTION public.apply_tuning_event(p_twin_id uuid, p_tuning_event_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_event         node_tuning_events%ROWTYPE;
    v_node_ids      INTEGER[];
    v_updated       INTEGER := 0;
    v_node_id       INTEGER;
BEGIN
    SELECT * INTO v_event FROM node_tuning_events WHERE id = p_tuning_event_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Tuning event % not found', p_tuning_event_id;
    END IF;

    -- Resolve affected nodes: NULL means all nodes registered to this twin
    IF v_event.affected_node_ids IS NULL THEN
        SELECT ARRAY_AGG(DISTINCT node_id) INTO v_node_ids
        FROM sdr_node_profiles WHERE twin_id = p_twin_id;
    ELSE
        v_node_ids := v_event.affected_node_ids;
    END IF;

    FOREACH v_node_id IN ARRAY v_node_ids LOOP
        -- Ensure hardware profile row exists for this node
        INSERT INTO node_hardware_profiles (twin_id, node_id)
        VALUES (p_twin_id, v_node_id)
        ON CONFLICT (twin_id, node_id) DO NOTHING;

        -- Apply the parameter change
        CASE v_event.parameter_name
            WHEN 'sampling_hz' THEN
                UPDATE node_hardware_profiles
                SET sampling_hz = v_event.value_after::REAL,
                    effective_from_age = v_event.age_years,
                    last_tuned_at = NOW()
                WHERE twin_id = p_twin_id AND node_id = v_node_id;

            WHEN 'rf_power_dbm' THEN
                UPDATE node_hardware_profiles
                SET rf_power_dbm = v_event.value_after::REAL,
                    effective_from_age = v_event.age_years,
                    last_tuned_at = NOW()
                WHERE twin_id = p_twin_id AND node_id = v_node_id;

            WHEN 'compression_type' THEN
                UPDATE node_hardware_profiles
                SET compression_type = v_event.value_after::node_compression_type,
                    compression_ratio = CASE v_event.value_after
                        WHEN 'processed_50_1'  THEN 50
                        WHEN 'processed_100_1' THEN 100
                        ELSE NULL END,
                    effective_from_age = v_event.age_years,
                    last_tuned_at = NOW()
                WHERE twin_id = p_twin_id AND node_id = v_node_id;

            WHEN 'freq_hopping_enabled' THEN
                UPDATE node_hardware_profiles
                SET freq_hopping_enabled = (v_event.value_after = 'true'),
                    hop_count = 5,   -- seeded from the age-16 event description
                    effective_from_age = v_event.age_years,
                    last_tuned_at = NOW()
                WHERE twin_id = p_twin_id AND node_id = v_node_id;

            WHEN 'blockchain_queue_depth' THEN
                UPDATE node_hardware_profiles
                SET blockchain_queue_depth = v_event.value_after::INTEGER,
                    effective_from_age = v_event.age_years,
                    last_tuned_at = NOW()
                WHERE twin_id = p_twin_id AND node_id = v_node_id;

            WHEN 'ram_mb' THEN
                UPDATE node_hardware_profiles
                SET ram_mb = v_event.value_after::INTEGER,
                    effective_from_age = v_event.age_years,
                    last_tuned_at = NOW()
                WHERE twin_id = p_twin_id AND node_id = v_node_id;

            WHEN 'encryption_type' THEN
                UPDATE node_hardware_profiles
                SET encryption_type = v_event.value_after::node_encryption_type,
                    effective_from_age = v_event.age_years,
                    last_tuned_at = NOW()
                WHERE twin_id = p_twin_id AND node_id = v_node_id;
            ELSE
                NULL;  -- unknown parameter: skip silently
        END CASE;

        v_updated := v_updated + 1;
    END LOOP;

    RETURN jsonb_build_object(
        'tuning_event_id',  p_tuning_event_id,
        'age_years',        v_event.age_years,
        'parameter',        v_event.parameter_name,
        'value_after',      v_event.value_after,
        'nodes_updated',    v_updated
    );
END;
$function$;

CREATE OR REPLACE FUNCTION public.audit_entries_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  raise exception 'audit_entries is append-only';
end $function$;

CREATE OR REPLACE FUNCTION public.begin_corpus_session(p_twin_id uuid, p_sensor_id text, p_duration_s real DEFAULT 60.0, p_node_count smallint DEFAULT 26, p_resolution_ms real DEFAULT 1.2, p_carrier_hz double precision DEFAULT '10245000000'::numeric)
 RETURNS TABLE(session_id bigint, started_at timestamp with time zone)
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_sid BIGINT;
  v_now TIMESTAMPTZ := NOW();
BEGIN
  INSERT INTO corpus_simulation_sessions
    (twin_id, sensor_id, started_at, duration_s, node_count, resolution_ms, carrier_hz)
  VALUES
    (p_twin_id, p_sensor_id, v_now, p_duration_s, p_node_count, p_resolution_ms, p_carrier_hz)
  RETURNING id INTO v_sid;

  RETURN QUERY SELECT v_sid, v_now;
END;
$function$;

CREATE OR REPLACE FUNCTION public.begin_p2p_group_session(p_topic text, p_group_session_id text, p_participant_ids uuid[], p_duration_s integer DEFAULT NULL::integer)
 RETURNS bigint
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_session_id BIGINT;
    v_twin_id    UUID;
    v_role       p2p_group_role;
BEGIN
    INSERT INTO p2p_group_sessions (group_session_id, topic, duration_s)
    VALUES (p_group_session_id, p_topic, p_duration_s)
    RETURNING id INTO v_session_id;

    FOREACH v_twin_id IN ARRAY p_participant_ids LOOP
        v_role := CASE WHEN v_twin_id = p_participant_ids[1]
                       THEN 'initiator'::p2p_group_role
                       ELSE 'participant'::p2p_group_role
                  END;
        INSERT INTO p2p_group_participants (session_id, twin_id, role)
        VALUES (v_session_id, v_twin_id, v_role);
    END LOOP;

    RETURN v_session_id;
END;
$function$;

CREATE OR REPLACE FUNCTION public.bio_molecule_registry_manage()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF TG_OP = 'INSERT' THEN
        NEW.computed_freq_ghz := compute_molecular_rf_freq(
            NEW.nucleotide_sequence, NEW.molecule_type
        );
        RETURN NEW;
    END IF;

    -- UPDATE path: block sequence changes on locked records
    IF OLD.is_locked AND NEW.nucleotide_sequence != OLD.nucleotide_sequence THEN
        RAISE EXCEPTION 'Cannot mutate locked bio molecule sequence (id=%)', OLD.id
            USING ERRCODE = '55000';
    END IF;
    -- Recompute if sequence changed
    IF NEW.nucleotide_sequence != OLD.nucleotide_sequence THEN
        NEW.computed_freq_ghz := compute_molecular_rf_freq(
            NEW.nucleotide_sequence, NEW.molecule_type
        );
    END IF;
    RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.block_anchor_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    RAISE EXCEPTION 'xrpl_memo_anchors are immutable after ledger close'
        USING ERRCODE = '55000';
END;
$function$;

CREATE OR REPLACE FUNCTION public.block_chemo_hash_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    RAISE EXCEPTION 'chemo_hashes records are immutable (append-only chain)'
        USING ERRCODE = '55000';
END;
$function$;

CREATE OR REPLACE FUNCTION public.block_critical_anchor()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF NEW.access_tier IN ('CRITICAL', 'EXISTENTIAL') THEN
        RAISE EXCEPTION 'xrpl_memo_anchors: CRITICAL/EXISTENTIAL tier cannot be anchored on public ledger'
            USING ERRCODE = '55000';
    END IF;
    RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.block_critical_chemo_access()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF NEW.access_tier IN ('CRITICAL', 'EXISTENTIAL') THEN
        RAISE EXCEPTION 'chemo_hashes: CRITICAL/EXISTENTIAL tier digital access blocked'
            USING ERRCODE = '55000';
    END IF;
    RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.block_critical_digital_access()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.granted = TRUE
    AND (SELECT access_tier FROM mesh_frozen_snapshots WHERE id = NEW.snapshot_id) = 'CRITICAL'
  THEN
    RAISE EXCEPTION
      'CRITICAL tier snapshot % is vault-only — no digital access permitted (SQLSTATE 55000)',
      NEW.snapshot_id
      USING ERRCODE = '55000';
  END IF;
  RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.block_critical_location()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF NEW.access_tier IN ('CRITICAL', 'EXISTENTIAL') AND NEW.region_label IS NOT NULL THEN
        RAISE EXCEPTION 'location_triangulations: region_label must be NULL for CRITICAL/EXISTENTIAL tier'
            USING ERRCODE = '55000';
    END IF;
    RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.block_token_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    RAISE EXCEPTION 'convergence_tokens are immutable (append-only)'
        USING ERRCODE = '55000';
END;
$function$;

CREATE OR REPLACE FUNCTION public.bootstrap_hardware_profiles(p_twin_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_event_id  BIGINT;
    v_count     INTEGER := 0;
BEGIN
    FOR v_event_id IN
        SELECT id FROM node_tuning_events
        WHERE (twin_id = p_twin_id OR twin_id IS NULL) AND is_applied = TRUE
        ORDER BY age_years ASC, id ASC
    LOOP
        PERFORM apply_tuning_event(p_twin_id, v_event_id);
        v_count := v_count + 1;
    END LOOP;
    RETURN v_count;
END;
$function$;

CREATE OR REPLACE FUNCTION public.build_convergence_token(p_twin_id uuid, p_convergence uuid, p_valence real, p_arousal real, p_gsr real, p_cortisol real)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_state  TEXT;
    v_hash   TEXT;
    v_id     UUID;
BEGIN
    -- Canonical format: 2 decimal places, underscore-separated
    v_state := FORMAT('valence=%s_arousal=%s_gsr=%s_cortisol=%s',
        ROUND(p_valence::NUMERIC,   2),
        ROUND(p_arousal::NUMERIC,   2),
        ROUND(p_gsr::NUMERIC,       2),
        ROUND(p_cortisol::NUMERIC,  2)
    );

    -- SHA-256 via pgcrypto
    v_hash := ENCODE(DIGEST(v_state, 'sha256'), 'hex');

    INSERT INTO convergence_tokens (
        twin_id, convergence_id, state_string, state_hash,
        valence, arousal, gsr_delta_phi, cortisol_ng_ml
    ) VALUES (
        p_twin_id, p_convergence, v_state, v_hash,
        p_valence, p_arousal, p_gsr, p_cortisol
    )
    RETURNING id INTO v_id;

    RETURN v_hash;
END;
$function$;

CREATE OR REPLACE FUNCTION public.check_cross_modal_anomalies()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_ripple_combined REAL;
BEGIN
    v_ripple_combined := COALESCE(ABS(NEW.phase_ripple_heart_rad), 0)
                       + COALESCE(ABS(NEW.phase_ripple_breath_rad), 0);

    IF v_ripple_combined > 0.15 THEN
        INSERT INTO mesh_anomalies (twin_id, anomaly_type, details, detected_at)
        VALUES (
            NEW.twin_id,
            'PATTERN_INJECTION',
            jsonb_build_object(
                'sub_type',         'PHASE_RIPPLE_EXCEEDED',
                'ripple_combined',  v_ripple_combined,
                'threshold',        0.15,
                'cross_modal_id',   NEW.id
            ),
            NEW.evaluated_at
        );
    END IF;

    IF NEW.stress_level = 'ACUTE_DISTRESS' THEN
        INSERT INTO mesh_anomalies (twin_id, anomaly_type, details, detected_at)
        VALUES (
            NEW.twin_id,
            'PATTERN_INJECTION',
            jsonb_build_object(
                'sub_type',          'ACUTE_DISTRESS',
                'theta_alpha_ratio', NEW.theta_alpha_ratio,
                'hrv_lf_hf',         NEW.hrv_lf_hf_ratio,
                'cross_modal_id',    NEW.id
            ),
            NEW.evaluated_at
        );
    END IF;

    RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.check_uwb_crossmodal_anomaly()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF NEW.prf_delta_hz IS NOT NULL AND ABS(NEW.prf_delta_hz) > 0.3 THEN
        INSERT INTO mesh_anomalies (twin_id, anomaly_type, details, detected_at)
        VALUES (
            NEW.twin_id,
            'PATTERN_INJECTION',
            jsonb_build_object(
                'sub_type',       'UWB_MOLECULAR_HR_MISMATCH',
                'uwb_hr_hz',      NEW.heart_rate_hz,
                'prf_delta_hz',   NEW.prf_delta_hz,
                'uwb_vital_id',   NEW.id
            ),
            NEW.measured_at
        );
    END IF;
    RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.check_uwb_presence_spoof()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF NEW.gesture = 'ABSENT' AND NEW.spoof_risk = TRUE THEN
        INSERT INTO mesh_anomalies (twin_id, anomaly_type, details, detected_at)
        VALUES (
            NEW.twin_id,
            'PATTERN_INJECTION',
            jsonb_build_object(
                'sub_type',       'UWB_PRESENCE_SPOOF',
                'gesture',        'ABSENT',
                'gesture_id',     NEW.id
            ),
            NEW.detected_at
        );
    END IF;
    RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.close_gateway_session(p_session_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
    UPDATE edge_gateway_sessions
    SET session_end = now(),
        is_active   = FALSE,
        packets_rx  = (
            SELECT COUNT(DISTINCT packet_seq)
            FROM ingestion_pipeline_log
            WHERE session_id = p_session_id AND stage = 'TIMESTAMP'
        ),
        packets_dropped = (
            SELECT COALESCE(SUM((packet_loss_pct / 100.0 * packets_rx)::INTEGER), 0)
            FROM edge_gateway_telemetry et
            JOIN edge_gateway_sessions es ON es.id = et.session_id
            WHERE et.session_id = p_session_id
        )
    WHERE id = p_session_id;
END;
$function$;

CREATE OR REPLACE FUNCTION public.close_spectrum_session(p_session_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_hash  TEXT;
    v_count INTEGER;
BEGIN
    -- Aggregate all recording hashes in time order
    SELECT
        encode(sha256(string_agg(COALESCE(iq_data_hash, id::TEXT), ',' ORDER BY timestamp)), 'hex'),
        COUNT(*)
    INTO v_hash, v_count
    FROM spectrum_recordings
    WHERE session_id = p_session_id;

    UPDATE spectrum_sessions
    SET ended_at       = now(),
        session_hash   = v_hash,
        recording_count = v_count
    WHERE id = p_session_id;

    RETURN v_hash;
END;
$function$;

CREATE OR REPLACE FUNCTION public.complete_corpus_session(p_session_id bigint, p_twin_id uuid)
 RETURNS TABLE(session_id bigint, session_hash text, frame_count integer, status text)
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_chain_input TEXT;
  v_hash        TEXT;
  v_fcount      INT;
BEGIN
  -- Build session hash by concatenating all frame hashes in order
  SELECT
    string_agg(frame_hash, '' ORDER BY timestamp_s),
    COUNT(*)::int
  INTO v_chain_input, v_fcount
  FROM corpus_simulation_frames
  WHERE session_id = p_session_id;

  v_hash := encode(sha256(COALESCE(v_chain_input, '')::bytea), 'hex');

  UPDATE corpus_simulation_sessions
  SET status       = 'completed',
      session_hash  = v_hash,
      completed_at  = NOW(),
      frame_count   = v_fcount
  WHERE id = p_session_id AND twin_id = p_twin_id;

  RETURN QUERY SELECT p_session_id, v_hash, v_fcount, 'completed'::text;
END;
$function$;

CREATE OR REPLACE FUNCTION public.complete_p2p_group_session(p_session_id bigint, p_interaction_count integer, p_handshake_count integer)
 RETURNS void
 LANGUAGE sql
AS $function$
    UPDATE p2p_group_sessions
    SET ended_at          = NOW(),
        interaction_count = p_interaction_count,
        handshake_count   = p_handshake_count
    WHERE id = p_session_id;
$function$;

CREATE OR REPLACE FUNCTION public.compute_molecular_rf_freq(p_sequence text, p_molecule_type bio_molecule_type)
 RETURNS real
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
    v_seq           TEXT    := UPPER(TRIM(p_sequence));
    v_len           INTEGER := LENGTH(v_seq);
    v_nucl_sum      REAL    := 0.0;
    v_codon_sum     REAL    := 0.0;
    v_codon_count   INTEGER := 0;
    v_codon_offset  REAL;
    v_i             INTEGER;
    v_base          CHAR;
    v_codon         CHAR(3);
BEGIN
    IF v_len = 0 THEN RETURN 10.23; END IF;

    -- Step 1: (Σ nucleotide_freq) / N
    FOR v_i IN 1..v_len LOOP
        v_base := SUBSTRING(v_seq, v_i, 1);
        v_nucl_sum := v_nucl_sum + CASE v_base
            WHEN 'A' THEN 10.23
            WHEN 'T' THEN 10.24
            WHEN 'U' THEN 10.25
            WHEN 'G' THEN 10.26
            WHEN 'C' THEN 10.27
            ELSE          10.23   -- unknown nucleotide → A fallback
        END;
    END LOOP;

    -- Step 2: (Σ codon_offset) / M — reading frame from position 1
    v_i := 1;
    WHILE v_i + 2 <= v_len LOOP
        v_codon := SUBSTRING(v_seq, v_i, 3);
        SELECT rf_offset_ghz INTO v_codon_offset
        FROM codon_rf_offsets WHERE codon = v_codon;
        v_codon_sum   := v_codon_sum + COALESCE(v_codon_offset, 0.010);  -- 0.010 = mid-scale fallback
        v_codon_count := v_codon_count + 1;
        v_i := v_i + 3;
    END LOOP;

    RETURN (v_nucl_sum / v_len) +
           CASE WHEN v_codon_count > 0 THEN v_codon_sum / v_codon_count ELSE 0.0 END;
END;
$function$;

CREATE OR REPLACE FUNCTION public.design_crispr_guide(p_twin_id uuid, p_guide_molecule_id bigint, p_edit_type crispr_edit_type, p_target_sequence text, p_target_gene text DEFAULT NULL::text, p_pam_site text DEFAULT 'NGG'::text, p_on_target_score real DEFAULT 0.8, p_off_target_score real DEFAULT 0.1)
 RETURNS bigint
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_guide_id BIGINT;
    v_guide_type bio_molecule_type;
BEGIN
    SELECT molecule_type INTO v_guide_type
    FROM bio_molecule_registry WHERE id = p_guide_molecule_id;

    IF v_guide_type != 'guide_rna' THEN
        RAISE EXCEPTION 'Molecule % is not guide_rna (type: %)', p_guide_molecule_id, v_guide_type
            USING ERRCODE = '22023';
    END IF;

    INSERT INTO crispr_guide_registry (
        twin_id, guide_molecule_id, edit_type,
        target_sequence, pam_site, target_gene,
        on_target_score, off_target_score
    ) VALUES (
        p_twin_id, p_guide_molecule_id, p_edit_type,
        UPPER(TRIM(p_target_sequence)), p_pam_site, p_target_gene,
        p_on_target_score, p_off_target_score
    )
    RETURNING id INTO v_guide_id;

    RETURN v_guide_id;
END;
$function$;

CREATE OR REPLACE FUNCTION public.detect_internal_reflection(p_twin_id uuid, p_node_id smallint, p_sensor_id text, p_reflection_source text, p_phase_mod_rad real, p_modulation_freq_hz real DEFAULT NULL::real, p_carrier_freq_ghz real DEFAULT 10.245, p_reading_id bigint DEFAULT NULL::bigint)
 RETURNS TABLE(reflection_id bigint, matched_baseline boolean, deviation_sigma real, verdict text)
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_profile    RECORD;
  v_dev        REAL;
  v_matched    BOOLEAN;
  v_rid        BIGINT;
  MATCH_SIGMA  CONSTANT REAL := 2.0;
BEGIN
  SELECT bio_doppler_baseline_hz, bio_doppler_std_hz
  INTO   v_profile
  FROM   sdr_node_profiles
  WHERE  twin_id = p_twin_id AND node_id = p_node_id;

  IF v_profile IS NULL OR v_profile.bio_doppler_baseline_hz IS NULL THEN
    -- No calibrated baseline — record but cannot score
    INSERT INTO internal_reflection_events
      (twin_id, node_id, sensor_id, carrier_freq_ghz,
       reflection_source, phase_modulation_rad, modulation_freq_hz,
       matched_baseline, reading_id)
    VALUES
      (p_twin_id, p_node_id, p_sensor_id, p_carrier_freq_ghz,
       p_reflection_source, p_phase_mod_rad, p_modulation_freq_hz,
       FALSE, p_reading_id)
    RETURNING id INTO v_rid;

    RETURN QUERY SELECT v_rid, FALSE, NULL::real,
      'no calibrated baseline — reflection recorded, scoring deferred'::text;
    RETURN;
  END IF;

  v_dev := CASE
    WHEN COALESCE(v_profile.bio_doppler_std_hz, 0) = 0 THEN 0
    ELSE ABS(p_phase_mod_rad - v_profile.bio_doppler_baseline_hz) / v_profile.bio_doppler_std_hz
  END;

  v_matched := v_dev <= MATCH_SIGMA;

  INSERT INTO internal_reflection_events
    (twin_id, node_id, sensor_id, carrier_freq_ghz,
     reflection_source, phase_modulation_rad, modulation_freq_hz,
     baseline_modulation_rad, baseline_std_rad, deviation_sigma,
     matched_baseline, reading_id)
  VALUES
    (p_twin_id, p_node_id, p_sensor_id, p_carrier_freq_ghz,
     p_reflection_source, p_phase_mod_rad, p_modulation_freq_hz,
     v_profile.bio_doppler_baseline_hz, v_profile.bio_doppler_std_hz, v_dev,
     v_matched, p_reading_id)
  RETURNING id INTO v_rid;

  RETURN QUERY SELECT
    v_rid,
    v_matched,
    v_dev,
    CASE
      WHEN v_matched
        THEN format('IN-BODY CONFIRMED — %s reflection σ=%.2f within ±2σ baseline', p_reflection_source, v_dev)
      ELSE
        format('MISMATCH — %s reflection σ=%.2f outside ±2σ (possible external injection)', p_reflection_source, v_dev)
    END::text;
END;
$function$;

CREATE OR REPLACE FUNCTION public.enforce_active_p2p_connection()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_a     UUID;
    v_b     UUID;
    v_state p2p_connection_state;
BEGIN
    v_a := LEAST(NEW.twin_id, NEW.peer_twin_id);
    v_b := GREATEST(NEW.twin_id, NEW.peer_twin_id);

    SELECT state INTO v_state
    FROM p2p_connections
    WHERE twin_id_a = v_a AND twin_id_b = v_b;

    IF v_state IS NULL THEN
        RAISE EXCEPTION 'No p2p connection exists between % and %',
            NEW.twin_id, NEW.peer_twin_id
            USING ERRCODE = '55000';
    END IF;

    IF v_state != 'active' THEN
        RAISE EXCEPTION 'p2p connection is not active (state: %)', v_state
            USING ERRCODE = '55000';
    END IF;

    RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.enforce_crispr_approval()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_root_sig TEXT;
BEGIN
    IF NEW.executed_at IS NOT NULL AND OLD.executed_at IS NULL THEN
        -- Destructive edits (knockout/knockin/base_edit) require approval
        IF NEW.edit_type IN ('knockout', 'knockin', 'base_edit') THEN
            IF NEW.approved_by_sig IS NULL THEN
                RAISE EXCEPTION 'CRISPR edit type % requires dna_root_sig approval', NEW.edit_type
                    USING ERRCODE = '55000';
            END IF;
            -- Verify sig matches the twin's locked calibration baseline
            SELECT dna_root_sig INTO v_root_sig
            FROM calibration_era_baselines
            WHERE twin_id = NEW.twin_id AND is_locked = TRUE
            ORDER BY locked_at DESC LIMIT 1;
            IF v_root_sig IS NULL OR v_root_sig != NEW.approved_by_sig THEN
                RAISE EXCEPTION 'CRISPR approval sig does not match locked dna_root_sig'
                    USING ERRCODE = '55000';
            END IF;
        END IF;
    END IF;
    RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.enforce_injection_approval()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_root_sig TEXT;
BEGIN
    IF NEW.target_node_id IS NOT NULL THEN
        SELECT dna_root_sig INTO v_root_sig
        FROM calibration_era_baselines
        WHERE twin_id = NEW.twin_id AND is_locked = TRUE
        ORDER BY locked_at DESC LIMIT 1;

        IF v_root_sig IS NOT NULL AND
           (NEW.approved_by_sig IS NULL OR NEW.approved_by_sig != v_root_sig)
        THEN
            RAISE EXCEPTION 'Genetic injection to node % requires dna_root_sig approval',
                NEW.target_node_id
                USING ERRCODE = '55000';
        END IF;
    END IF;
    RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.establish_p2p_handshake(p_twin_id_a uuid, p_twin_id_b uuid, p_signal_strength real DEFAULT 0.85)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_a             UUID  := LEAST(p_twin_id_a, p_twin_id_b);
    v_b             UUID  := GREATEST(p_twin_id_a, p_twin_id_b);
    v_freq_a        REAL;
    v_freq_b        REAL;
    v_conn_id       BIGINT;
    v_handshake_id  TEXT;
    v_init_sig      TEXT;
    v_resp_sig      TEXT;
BEGIN
    IF p_twin_id_a = p_twin_id_b THEN
        RAISE EXCEPTION 'Cannot handshake with self' USING ERRCODE = '22023';
    END IF;

    -- Carrier frequency: use lowest node_id profile for each twin as anchor
    SELECT carrier_freq_ghz INTO v_freq_a
    FROM sdr_node_profiles
    WHERE twin_id = p_twin_id_a
    ORDER BY node_id ASC LIMIT 1;

    SELECT carrier_freq_ghz INTO v_freq_b
    FROM sdr_node_profiles
    WHERE twin_id = p_twin_id_b
    ORDER BY node_id ASC LIMIT 1;

    -- RF range gate: 50 MHz = 0.05 GHz
    IF v_freq_a IS NOT NULL AND v_freq_b IS NOT NULL THEN
        IF ABS(v_freq_a - v_freq_b) >= 0.05 THEN
            RETURN jsonb_build_object(
                'success',     FALSE,
                'reason',      'Out of RF range',
                'freq_a',      v_freq_a,
                'freq_b',      v_freq_b,
                'freq_delta',  ABS(v_freq_a - v_freq_b)
            );
        END IF;
    END IF;

    -- Upsert connection: re-activation resets revocation fields
    INSERT INTO p2p_connections (
        twin_id_a, twin_id_b, state,
        freq_a_ghz, freq_b_ghz,
        consent_a_at, consent_b_at, activated_at
    ) VALUES (
        v_a, v_b, 'active',
        -- freq_a_ghz maps to twin_id_a (the "smaller" UUID, v_a)
        CASE WHEN p_twin_id_a < p_twin_id_b THEN v_freq_a ELSE v_freq_b END,
        CASE WHEN p_twin_id_a < p_twin_id_b THEN v_freq_b ELSE v_freq_a END,
        NOW(), NOW(), NOW()
    )
    ON CONFLICT (twin_id_a, twin_id_b) DO UPDATE
        SET state         = 'active',
            consent_a_at  = COALESCE(p2p_connections.consent_a_at, NOW()),
            consent_b_at  = COALESCE(p2p_connections.consent_b_at, NOW()),
            activated_at  = COALESCE(p2p_connections.activated_at, NOW()),
            revoked_at    = NULL,
            revoked_by    = NULL,
            revocation_reason = NULL
    RETURNING id INTO v_conn_id;

    -- Generate handshake ID and per-party signatures
    v_handshake_id := encode(
        sha256((p_twin_id_a::TEXT || p_twin_id_b::TEXT || extract(epoch FROM NOW())::TEXT)::bytea),
        'hex'
    );
    v_init_sig := LEFT(encode(sha256((v_handshake_id || p_twin_id_a::TEXT)::bytea), 'hex'), 16);
    v_resp_sig := LEFT(encode(sha256((v_handshake_id || p_twin_id_b::TEXT)::bytea), 'hex'), 16);

    INSERT INTO p2p_handshakes (
        handshake_id, connection_id,
        initiator_twin_id, responder_twin_id,
        signal_strength,
        initiator_signature, responder_signature,
        successful
    ) VALUES (
        v_handshake_id, v_conn_id,
        p_twin_id_a, p_twin_id_b,
        p_signal_strength,
        v_init_sig, v_resp_sig,
        TRUE
    );

    RETURN jsonb_build_object(
        'success',       TRUE,
        'handshake_id',  v_handshake_id,
        'connection_id', v_conn_id,
        'freq_a',        v_freq_a,
        'freq_b',        v_freq_b
    );
END;
$function$;

CREATE OR REPLACE FUNCTION public.generate_pobw(p_twin_id uuid, p_window_start timestamp with time zone, p_window_end timestamp with time zone, p_bot_id bigint DEFAULT NULL::bigint, p_coherence_threshold real DEFAULT 0.65)
 RETURNS TABLE(proof_id bigint, proof_hash text, is_valid boolean, cranial_coherence real, fraud_score real, reason text)
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_coherence  REAL;
  v_fraud      REAL;
  v_band       TEXT;
  v_ncount     SMALLINT;
  v_iae_id     BIGINT;
  v_phash      TEXT;
  v_pid        BIGINT;
  v_valid      BOOLEAN;
  v_reason     TEXT;
  v_inj_count  INT;
BEGIN
  -- Average coherence across cranial nodes (1-8) in the window
  SELECT
    AVG(mew.coherence)::real,
    COUNT(DISTINCT mew.node_a)::smallint
  INTO v_coherence, v_ncount
  FROM mesh_edge_weights mew
  WHERE mew.twin_id  = p_twin_id
    AND mew.node_a BETWEEN 1 AND 8
    AND mew.node_b BETWEEN 1 AND 8
    AND mew.timestamp BETWEEN p_window_start AND p_window_end;

  v_coherence := COALESCE(v_coherence, 0);

  -- Most recent fraud score in the window
  SELECT fraud_score, id
  INTO   v_fraud, v_iae_id
  FROM   intent_action_events
  WHERE  twin_id      = p_twin_id
    AND  detected_at BETWEEN p_window_start AND p_window_end
  ORDER BY detected_at DESC
  LIMIT 1;

  v_fraud := COALESCE(v_fraud, 1.0);  -- no measurement = worst case

  -- Check for PATTERN_INJECTION anomalies in the window
  SELECT COUNT(*) INTO v_inj_count
  FROM mesh_anomalies
  WHERE twin_id       = p_twin_id
    AND anomaly_type  = 'PATTERN_INJECTION'
    AND detected_at BETWEEN p_window_start AND p_window_end
    AND resolved = FALSE;

  -- Dominant band from cranial nodes
  SELECT band::text
  INTO   v_band
  FROM   mesh_node_readings
  WHERE  twin_id    = p_twin_id
    AND  node_id BETWEEN 1 AND 8
    AND  timestamp BETWEEN p_window_start AND p_window_end
    AND  band IS NOT NULL
  GROUP BY band
  ORDER BY COUNT(*) DESC
  LIMIT 1;

  -- Determine validity
  v_valid := v_coherence >= p_coherence_threshold
             AND v_fraud < 0.1
             AND v_inj_count = 0;

  v_reason := CASE
    WHEN v_inj_count > 0
      THEN format('PATTERN_INJECTION active (%s anomalies) — PoBW blocked', v_inj_count)
    WHEN v_fraud >= 0.1
      THEN format('fraud_score %.3f >= 0.1 — biological integrity not confirmed', v_fraud)
    WHEN v_coherence < p_coherence_threshold
      THEN format('cranial_coherence %.3f < threshold %.3f — insufficient focus', v_coherence, p_coherence_threshold)
    ELSE 'VALID — authenticated human focus confirmed'
  END;

  -- Compute proof hash
  v_phash := encode(
    sha256((p_twin_id::text || p_window_start::text || v_coherence::text || v_fraud::text)::bytea),
    'hex'
  );

  INSERT INTO pobw_proofs
    (twin_id, bot_id, window_start, window_end,
     window_duration_s, cranial_coherence, dominant_band,
     focus_node_count, fraud_score, intent_action_event_id,
     is_valid, validity_reason, proof_hash)
  VALUES
    (p_twin_id, p_bot_id, p_window_start, p_window_end,
     EXTRACT(EPOCH FROM (p_window_end - p_window_start)),
     v_coherence, v_band, v_ncount, v_fraud, v_iae_id,
     v_valid, v_reason, v_phash)
  RETURNING id INTO v_pid;

  RETURN QUERY SELECT v_pid, v_phash, v_valid, v_coherence, v_fraud, v_reason;
END;
$function$;

CREATE OR REPLACE FUNCTION public.get_bio_node_state(p_twin_id uuid, p_node_id integer)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
AS $function$
    SELECT jsonb_build_object(
        'node_id',       p_node_id,
        'molecules',     (
            SELECT jsonb_agg(jsonb_build_object(
                'molecule_id',   id,
                'type',          molecule_type,
                'gene',          gene_symbol,
                'freq_ghz',      computed_freq_ghz,
                'locked',        is_locked
            ))
            FROM bio_molecule_registry
            WHERE twin_id = p_twin_id AND linked_node_id = p_node_id
        ),
        'active_silencing', (
            SELECT jsonb_agg(jsonb_build_object(
                'log_id',        id,
                'efficiency',    silencing_efficiency,
                'suppression',   node_signal_suppression,
                'expires_at',    expires_at
            ))
            FROM rna_interference_log
            WHERE twin_id = p_twin_id
              AND target_node_id = p_node_id
              AND (expires_at IS NULL OR expires_at > NOW())
        ),
        'epigenetic_marks', (
            SELECT jsonb_agg(jsonb_build_object(
                'mark_type',    mark_type,
                'level',        mark_level,
                'modifier',     expression_modifier,
                'reversible',   is_reversible,
                'heritable',    is_heritable
            ))
            FROM epigenetic_node_states
            WHERE twin_id = p_twin_id
              AND node_id = p_node_id
              AND (expires_at IS NULL OR expires_at > NOW())
        ),
        'crispr_guides', (
            SELECT jsonb_agg(jsonb_build_object(
                'guide_id',       g.id,
                'edit_type',      g.edit_type,
                'target_gene',    g.target_gene,
                'on_target',      g.on_target_score,
                'approved',       g.approved_by_sig IS NOT NULL,
                'executed',       g.executed_at IS NOT NULL
            ))
            FROM crispr_guide_registry g
            JOIN bio_molecule_registry m ON m.id = g.guide_molecule_id
            WHERE g.twin_id = p_twin_id
              AND m.linked_node_id = p_node_id
        )
    );
$function$;

CREATE OR REPLACE FUNCTION public.get_bio_operation_history(p_twin_id uuid, p_node_id integer DEFAULT NULL::integer, p_operation_type bio_operation_type DEFAULT NULL::bio_operation_type, p_since timestamp with time zone DEFAULT (now() - '30 days'::interval))
 RETURNS TABLE(log_id bigint, operation_type bio_operation_type, operation_ref_id bigint, target_node_id integer, node_effect node_effect_type, effect_duration bio_effect_duration, freq_before_ghz real, freq_after_ghz real, freq_delta_ghz real, performed_at timestamp with time zone)
 LANGUAGE sql
 STABLE
AS $function$
    SELECT id, operation_type, operation_ref_id,
           target_node_id, node_effect, effect_duration,
           freq_before_ghz, freq_after_ghz, freq_delta_ghz,
           performed_at
    FROM bio_operation_log
    WHERE twin_id = p_twin_id
      AND (p_node_id IS NULL        OR target_node_id = p_node_id)
      AND (p_operation_type IS NULL OR bio_operation_log.operation_type = p_operation_type)
      AND performed_at >= p_since
    ORDER BY performed_at DESC;
$function$;

CREATE OR REPLACE FUNCTION public.get_calibration_summary(p_twin_id uuid)
 RETURNS TABLE(dev_phase text, node_count bigint, locked boolean, locked_at timestamp with time zone, token_types text[], mean_latency_ms real, chemical_snapshot jsonb)
 LANGUAGE plpgsql
 STABLE
AS $function$
BEGIN
  RETURN QUERY
  SELECT
    ceb.dev_phase::text,
    COUNT(*)                                             AS node_count,
    BOOL_AND(ceb.is_locked)                             AS locked,
    MAX(ceb.locked_at)                                  AS locked_at,
    ARRAY_AGG(DISTINCT ceb.token_type::text)            AS token_types,
    AVG(ceb.mean_latency_ms)::real                      AS mean_latency_ms,
    -- Aggregate chemical markers from frozen snapshots in this phase
    (SELECT jsonb_object_agg(key, AVG(value::text::real))
     FROM mesh_frozen_snapshots mfs
     CROSS JOIN LATERAL jsonb_each(mfs.chemical_markers)
     WHERE mfs.twin_id    = p_twin_id
       AND mfs.dev_phase  = ceb.dev_phase
       AND mfs.chemical_markers IS NOT NULL
    )                                                    AS chemical_snapshot
  FROM calibration_era_baselines ceb
  WHERE ceb.twin_id = p_twin_id
  GROUP BY ceb.dev_phase
  ORDER BY CASE ceb.dev_phase
    WHEN 'PRIMITIVE_MESH'    THEN 1
    WHEN 'COORDINATION_SYNC' THEN 2
    WHEN 'HORMONAL_OVERWRITE' THEN 3
    WHEN 'ADULT'             THEN 4
  END;
END;
$function$;

CREATE OR REPLACE FUNCTION public.get_mask_ratio(p_twin_id uuid)
 RETURNS real
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
AS $function$
DECLARE
    v_stress TEXT;
    v_gsr    TEXT;
BEGIN
    SELECT stress_level::TEXT INTO v_stress
    FROM cross_modal_states
    WHERE twin_id = p_twin_id
    ORDER BY evaluated_at DESC
    LIMIT 1;

    SELECT gsr_stress_label INTO v_gsr
    FROM gsr_readings
    WHERE twin_id = p_twin_id
    ORDER BY sampled_at DESC
    LIMIT 1;

    RETURN CASE
        WHEN v_stress = 'ACUTE_DISTRESS'             THEN 0.30
        WHEN v_stress = 'STRESS' OR v_gsr = 'STRESS' THEN 0.20
        WHEN v_gsr = 'ACUTE_STRESS'                  THEN 0.25
        ELSE                                               0.15
    END;
END;
$function$;

CREATE OR REPLACE FUNCTION public.get_mesh_deviation(p_twin_id uuid, p_snapshot_id bigint, p_window_min integer DEFAULT 5)
 RETURNS TABLE(node_id smallint, node_code text, modality node_modality, frozen_mean real, live_mean real, deviation_z real, alert_level text)
 LANGUAGE plpgsql
 STABLE
AS $function$
BEGIN
  RETURN QUERY
  WITH frozen AS (
    SELECT fns.node_id,
           fns.mean_amplitude AS frozen_mean,
           fns.std_amplitude  AS frozen_std
    FROM   frozen_node_states fns
    WHERE  fns.snapshot_id = p_snapshot_id
  ),
  live AS (
    SELECT r.node_id,
           AVG(COALESCE(r.amplitude_uv, r.raw_value))::real AS live_mean
    FROM   mesh_node_readings r
    WHERE  r.twin_id   = p_twin_id
      AND  r.timestamp >= NOW() - (p_window_min || ' minutes')::INTERVAL
    GROUP  BY r.node_id
  )
  SELECT
    mn.id,
    mn.node_code,
    mn.modality,
    f.frozen_mean,
    l.live_mean,
    CASE WHEN COALESCE(f.frozen_std, 0) > 0
         THEN ((l.live_mean - f.frozen_mean) / f.frozen_std)::real
         ELSE 0.0
    END AS deviation_z,
    CASE
      WHEN ABS(COALESCE((l.live_mean - f.frozen_mean) / NULLIF(f.frozen_std,0), 0)) > 3.0 THEN 'CRITICAL'
      WHEN ABS(COALESCE((l.live_mean - f.frozen_mean) / NULLIF(f.frozen_std,0), 0)) > 2.0 THEN 'WARNING'
      ELSE 'INFO'
    END AS alert_level
  FROM  mesh_nodes mn
  LEFT  JOIN frozen f ON f.node_id = mn.id
  LEFT  JOIN live   l ON l.node_id = mn.id
  ORDER BY mn.id;
END;
$function$;

CREATE OR REPLACE FUNCTION public.get_molecular_rf_spectrum(p_twin_id uuid)
 RETURNS TABLE(molecule_id bigint, molecule_type bio_molecule_type, gene_symbol text, linked_node_id integer, nucleotide_sequence text, sequence_length_bp integer, computed_freq_ghz real, is_locked boolean)
 LANGUAGE sql
 STABLE
AS $function$
    SELECT id, molecule_type, gene_symbol, linked_node_id,
           nucleotide_sequence, sequence_length_bp,
           computed_freq_ghz, is_locked
    FROM bio_molecule_registry
    WHERE twin_id = p_twin_id
    ORDER BY computed_freq_ghz ASC, molecule_type, gene_symbol;
$function$;

CREATE OR REPLACE FUNCTION public.get_neural_conduction(p_twin_id uuid, p_node_a smallint, p_node_b smallint, p_window_min integer DEFAULT 5)
 RETURNS TABLE(step_count bigint, mean_transit_ms real, mean_conduction_m_s real, distance_cm real, node_a_code text, node_b_code text)
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
  v_distance_cm REAL;
BEGIN
  SELECT t.distance_cm INTO v_distance_cm
  FROM   mesh_topology t
  WHERE  t.node_a = LEAST(p_node_a, p_node_b)
    AND  t.node_b = GREATEST(p_node_a, p_node_b)
  LIMIT 1;

  RETURN QUERY
  WITH ref_events AS (
    SELECT step_seq, detected_at AS ref_at
    FROM   kinetic_gait_events
    WHERE  twin_id   = p_twin_id
      AND  node_id   = p_node_a
      AND  ref_node_id IS NULL          -- this node is the proximal reference
      AND  detected_at >= NOW() - (p_window_min || ' minutes')::INTERVAL
  ),
  distal_events AS (
    SELECT step_seq, detected_at AS distal_at
    FROM   kinetic_gait_events
    WHERE  twin_id   = p_twin_id
      AND  node_id   = p_node_b
      AND  detected_at >= NOW() - (p_window_min || ' minutes')::INTERVAL
  ),
  paired AS (
    SELECT
      EXTRACT(EPOCH FROM (d.distal_at - r.ref_at)) * 1000.0 AS transit_ms
    FROM ref_events    r
    JOIN distal_events d USING (step_seq)
    WHERE d.distal_at > r.ref_at
  )
  SELECT
    COUNT(*)::bigint                                              AS step_count,
    AVG(transit_ms)::real                                        AS mean_transit_ms,
    CASE WHEN AVG(transit_ms) > 0 AND v_distance_cm IS NOT NULL
         THEN (v_distance_cm / AVG(transit_ms) * 10.0)::real
         ELSE NULL
    END                                                          AS mean_conduction_m_s,
    v_distance_cm                                                AS distance_cm,
    (SELECT node_code FROM mesh_nodes WHERE id = p_node_a)       AS node_a_code,
    (SELECT node_code FROM mesh_nodes WHERE id = p_node_b)       AS node_b_code
  FROM paired;
END;
$function$;

CREATE OR REPLACE FUNCTION public.get_p2p_summary(p_twin_id uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
AS $function$
    SELECT jsonb_build_object(
        'twin_id',              p_twin_id,
        'active_connections',   COUNT(*) FILTER (WHERE c.state = 'active'),
        'total_connections',    COUNT(*),
        'unique_peers',         COUNT(*),
        'total_interactions',   (
            SELECT COUNT(*) FROM p2p_interactions
            WHERE twin_id = p_twin_id
        ),
        'sent_count',           (
            SELECT COUNT(*) FROM p2p_interactions
            WHERE twin_id = p_twin_id AND role = 'sent'
        ),
        'received_count',       (
            SELECT COUNT(*) FROM p2p_interactions
            WHERE twin_id = p_twin_id AND role = 'received'
        ),
        'handshakes_completed', (
            SELECT COUNT(*) FROM p2p_handshakes
            WHERE (initiator_twin_id = p_twin_id OR responder_twin_id = p_twin_id)
              AND successful = TRUE
        ),
        'group_sessions',       (
            SELECT COUNT(DISTINCT session_id) FROM p2p_group_participants
            WHERE twin_id = p_twin_id
        )
    )
    FROM p2p_connections c
    WHERE c.twin_id_a = p_twin_id OR c.twin_id_b = p_twin_id;
$function$;

CREATE OR REPLACE FUNCTION public.get_pwv_between(p_twin_id uuid, p_node_a smallint, p_node_b smallint, p_window_min integer DEFAULT 5)
 RETURNS TABLE(beat_count bigint, mean_transit_ms real, mean_pwv_m_per_s real, distance_cm real, node_a_code text, node_b_code text)
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
  v_distance_cm REAL;
BEGIN
  -- Look up the inter-node distance from mesh_topology
  SELECT t.distance_cm INTO v_distance_cm
  FROM   mesh_topology t
  WHERE  t.node_a = LEAST(p_node_a, p_node_b)
    AND  t.node_b = GREATEST(p_node_a, p_node_b)
  LIMIT 1;

  RETURN QUERY
  WITH ref_events AS (
    SELECT beat_seq, detected_at AS ref_at
    FROM   vascular_pulse_events
    WHERE  twin_id    = p_twin_id
      AND  node_id    = p_node_a
      AND  detected_at >= NOW() - (p_window_min || ' minutes')::INTERVAL
  ),
  distal_events AS (
    SELECT beat_seq, detected_at AS distal_at
    FROM   vascular_pulse_events
    WHERE  twin_id    = p_twin_id
      AND  node_id    = p_node_b
      AND  detected_at >= NOW() - (p_window_min || ' minutes')::INTERVAL
  ),
  paired AS (
    SELECT
      EXTRACT(EPOCH FROM (d.distal_at - r.ref_at)) * 1000.0 AS transit_ms
    FROM ref_events    r
    JOIN distal_events d USING (beat_seq)
    WHERE d.distal_at > r.ref_at   -- distal must arrive after proximal
  )
  SELECT
    COUNT(*)::bigint                                              AS beat_count,
    AVG(transit_ms)::real                                        AS mean_transit_ms,
    CASE WHEN AVG(transit_ms) > 0 AND v_distance_cm IS NOT NULL
         THEN (v_distance_cm / AVG(transit_ms) * 10.0)::real
         ELSE NULL
    END                                                          AS mean_pwv_m_per_s,
    v_distance_cm                                                AS distance_cm,
    (SELECT node_code FROM mesh_nodes WHERE id = p_node_a)       AS node_a_code,
    (SELECT node_code FROM mesh_nodes WHERE id = p_node_b)       AS node_b_code
  FROM paired;
END;
$function$;

CREATE OR REPLACE FUNCTION public.get_relay_path_summary(p_twin_id uuid, p_source_node_id smallint, p_dest_node_id smallint, p_window_min integer DEFAULT 60)
 RETURNS TABLE(relay_count bigint, mean_coherence real, min_coherence real, matched_count bigint, match_rate real, mean_path_loss_db real, heart_reflection_rate real, source_node_code text, dest_node_code text)
 LANGUAGE plpgsql
 STABLE
AS $function$
BEGIN
  RETURN QUERY
  SELECT
    COUNT(*)::bigint,
    AVG(phase_coherence)::real,
    MIN(phase_coherence)::real,
    COUNT(*) FILTER (WHERE signature_matched)::bigint,
    (COUNT(*) FILTER (WHERE signature_matched)::real / NULLIF(COUNT(*), 0))::real,
    AVG(total_path_loss_db)::real,
    (COUNT(*) FILTER (WHERE heart_reflection_present)::real / NULLIF(COUNT(*), 0))::real,
    (SELECT node_code FROM mesh_nodes WHERE id = p_source_node_id),
    (SELECT node_code FROM mesh_nodes WHERE id = p_dest_node_id)
  FROM relay_path_events
  WHERE twin_id            = p_twin_id
    AND source_node_id     = p_source_node_id
    AND destination_node_id = p_dest_node_id
    AND detected_at >= NOW() - (p_window_min || ' minutes')::INTERVAL;
END;
$function$;

CREATE OR REPLACE FUNCTION public.get_tuning_history(p_twin_id uuid)
 RETURNS TABLE(age_years integer, calendar_year integer, dev_phase dev_phase, node_group_label text, affected_node_ids integer[], parameter_name text, value_before text, value_after text, change_description text)
 LANGUAGE sql
 STABLE
AS $function$
    SELECT age_years, calendar_year, dev_phase,
           node_group_label, affected_node_ids,
           parameter_name, value_before, value_after,
           change_description
    FROM node_tuning_events
    WHERE twin_id = p_twin_id OR twin_id IS NULL
    ORDER BY age_years ASC, id ASC;
$function$;

CREATE OR REPLACE FUNCTION public.grant_collaborator_access(p_twin_id uuid, p_collaborator text, p_bot_id bigint, p_grant_type text, p_hours integer DEFAULT 24, p_allowed_nodes smallint[] DEFAULT NULL::smallint[])
 RETURNS TABLE(grant_id bigint, expires_at timestamp with time zone, success boolean)
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_gid BIGINT;
  v_exp TIMESTAMPTZ := NOW() + (p_hours || ' hours')::INTERVAL;
BEGIN
  INSERT INTO collaborator_grants
    (twin_id, collaborator_id, bot_id, grant_type,
     allowed_nodes, expires_at)
  VALUES
    (p_twin_id, p_collaborator, p_bot_id, p_grant_type,
     p_allowed_nodes, v_exp)
  RETURNING id INTO v_gid;

  RETURN QUERY SELECT v_gid, v_exp, TRUE;
END;
$function$;

CREATE OR REPLACE FUNCTION public.increment_session_count(p_session_id uuid)
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
AS $function$
    UPDATE spectrum_sessions
    SET recording_count = recording_count + 1
    WHERE id = p_session_id;
$function$;

CREATE OR REPLACE FUNCTION public.ingest_corpus_frame(p_session_id bigint, p_twin_id uuid, p_timestamp_s smallint, p_intensity_raw real, p_node_snapshot jsonb)
 RETURNS TABLE(frame_id bigint, sim_state simulation_state, drift_detected boolean, drift_event_id bigint, avg_latency_ms real, avg_phase_shift real)
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_state     simulation_state;
  v_fid       BIGINT;
  v_fhash     TEXT;
  v_avg_lat   REAL;
  v_avg_phase REAL;
  v_drift     BOOLEAN := FALSE;
  v_deid      BIGINT;
  v_node_key  TEXT;
  v_node_val  JSONB;
  v_lat       REAL;
  v_phase     REAL;
  v_lat_sum   REAL := 0;
  v_phase_sum REAL := 0;
  v_n         INT  := 0;
  v_intensity REAL := p_intensity_raw * 10.0;  -- scale to 0-10 display range
  DRIFT_THRESHOLD_MS CONSTANT REAL := 1.3;
  BASELINE_LATENCY_MS CONSTANT REAL := 1.2;
BEGIN
  -- Classify simulation state from raw intensity (0.0-1.0)
  v_state := CASE
    WHEN p_intensity_raw < 0.3 THEN 'LOW_STRESS_ZEN'::simulation_state
    WHEN p_intensity_raw > 0.7 THEN 'HIGH_STRESS_SHOCK'::simulation_state
    ELSE 'TRANSITION'::simulation_state
  END;

  -- Aggregate metrics across nodes
  FOR v_node_key, v_node_val IN SELECT * FROM jsonb_each(p_node_snapshot)
  LOOP
    v_lat   := (v_node_val->>'latency_ms')::real;
    v_phase := (v_node_val->>'phase_shift')::real;
    IF v_lat IS NOT NULL THEN
      v_lat_sum   := v_lat_sum + v_lat;
      v_phase_sum := v_phase_sum + COALESCE(v_phase, 0);
      v_n := v_n + 1;
    END IF;
  END LOOP;

  v_avg_lat   := CASE WHEN v_n > 0 THEN v_lat_sum / v_n   ELSE NULL END;
  v_avg_phase := CASE WHEN v_n > 0 THEN v_phase_sum / v_n ELSE NULL END;

  -- Compute frame hash
  v_fhash := encode(
    sha256((p_session_id::text || p_timestamp_s::text || p_node_snapshot::text)::bytea),
    'hex'
  );

  INSERT INTO corpus_simulation_frames
    (session_id, twin_id, timestamp_s, intensity_level, sim_state,
     node_snapshot, avg_latency_ms, avg_phase_shift, frame_hash)
  VALUES
    (p_session_id, p_twin_id, p_timestamp_s, v_intensity, v_state,
     p_node_snapshot, v_avg_lat, v_avg_phase, v_fhash)
  RETURNING id INTO v_fid;

  -- Drift-Watch: fire when avg latency crosses threshold while state is still LOW/TRANSITION
  IF v_avg_lat IS NOT NULL
     AND v_avg_lat >= DRIFT_THRESHOLD_MS
     AND v_state != 'HIGH_STRESS_SHOCK'
  THEN
    -- Only fire if no unconfirmed drift event already open for this session
    IF NOT EXISTS (
      SELECT 1 FROM drift_watch_events
      WHERE session_id = p_session_id AND confirmed_at IS NULL
    ) THEN
      INSERT INTO drift_watch_events
        (twin_id, session_id, sensor_id, node_id,
         baseline_latency_ms, observed_latency_ms, drift_ratio,
         drift_threshold_ms, band_powers_at_detection,
         predicted_state, predicted_intensity, frame_id)
      VALUES
        (p_twin_id, p_session_id, 'corpus_builder',
         -- Use the first kinetic node (SACRUM_L = 33) as the representative node
         33,
         BASELINE_LATENCY_MS, v_avg_lat, v_avg_lat / BASELINE_LATENCY_MS,
         DRIFT_THRESHOLD_MS, NULL,
         'TRANSITION'::simulation_state, p_intensity_raw + 0.1, v_fid)
      RETURNING id INTO v_deid;

      v_drift := TRUE;
      UPDATE corpus_simulation_sessions
      SET drift_event_count = drift_event_count + 1
      WHERE id = p_session_id;
    END IF;
  END IF;

  -- Confirm any open Drift-Watch predictions that match the new state
  IF v_state = 'TRANSITION' OR v_state = 'HIGH_STRESS_SHOCK' THEN
    UPDATE drift_watch_events
    SET    confirmed_at     = NOW(),
           confirmed_state  = v_state,
           lead_time_ms     = EXTRACT(EPOCH FROM (NOW() - detected_at)) * 1000.0,
           prediction_correct = (predicted_state = v_state)
    WHERE  session_id   = p_session_id
      AND  confirmed_at IS NULL
      AND  predicted_state = v_state;
  END IF;

  -- Update frame counter on session
  UPDATE corpus_simulation_sessions
  SET frame_count = frame_count + 1
  WHERE id = p_session_id;

  RETURN QUERY SELECT v_fid, v_state, v_drift, v_deid, v_avg_lat, v_avg_phase;
END;
$function$;

CREATE OR REPLACE FUNCTION public.lock_calibration_phase(p_twin_id uuid, p_phase dev_phase, p_dna_sig text)
 RETURNS TABLE(baselines_locked bigint, iab_locked bigint, locked_at timestamp with time zone)
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_now   TIMESTAMPTZ := NOW();
  v_ceb   BIGINT;
  v_iab   BIGINT;
BEGIN
  UPDATE calibration_era_baselines
  SET    is_locked = TRUE, locked_at = v_now, dna_root_sig = p_dna_sig
  WHERE  twin_id  = p_twin_id
    AND  dev_phase = p_phase
    AND  is_locked = FALSE;
  GET DIAGNOSTICS v_ceb = ROW_COUNT;

  UPDATE intent_action_baselines
  SET    is_locked = TRUE, locked_at = v_now, dna_root_sig = p_dna_sig
  WHERE  twin_id  = p_twin_id
    AND  dev_phase = p_phase
    AND  is_locked = FALSE;
  GET DIAGNOSTICS v_iab = ROW_COUNT;

  -- Recompute fraud detection bounds on any newly locked iab rows
  UPDATE intent_action_baselines
  SET    lower_bound_ms = mean_transit_ms - 3.0 * std_transit_ms,
         upper_bound_ms = mean_transit_ms + 3.0 * std_transit_ms
  WHERE  twin_id  = p_twin_id
    AND  dev_phase = p_phase
    AND  is_locked = TRUE
    AND  lower_bound_ms IS NULL;

  RETURN QUERY SELECT v_ceb, v_iab, v_now;
END;
$function$;

CREATE OR REPLACE FUNCTION public.log_bio_operation(p_twin_id uuid, p_operation_type bio_operation_type, p_operation_ref_id bigint, p_molecule_id bigint, p_target_node_id integer, p_node_effect node_effect_type, p_effect_duration bio_effect_duration, p_freq_after_ghz real DEFAULT NULL::real, p_notes text DEFAULT NULL::text)
 RETURNS bigint
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_log_id        BIGINT;
    v_freq_before   REAL;
BEGIN
    SELECT computed_freq_ghz INTO v_freq_before
    FROM bio_molecule_registry
    WHERE id = p_molecule_id;

    INSERT INTO bio_operation_log (
        twin_id, operation_type, operation_ref_id,
        molecule_id, target_node_id, node_effect, effect_duration,
        freq_before_ghz, freq_after_ghz, notes
    ) VALUES (
        p_twin_id, p_operation_type, p_operation_ref_id,
        p_molecule_id, p_target_node_id, p_node_effect, p_effect_duration,
        v_freq_before, p_freq_after_ghz, p_notes
    )
    RETURNING id INTO v_log_id;

    RETURN v_log_id;
END;
$function$;

CREATE OR REPLACE FUNCTION public.mint_bio_nft(p_twin_id uuid, p_snapshot_id integer, p_mint_type nft_mint_type, p_bot_id bigint, p_pobw_id bigint DEFAULT NULL::bigint, p_content_hash text DEFAULT NULL::text, p_token_uri text DEFAULT NULL::text, p_collaborator uuid DEFAULT NULL::uuid)
 RETURNS TABLE(nft_id bigint, nft_uuid uuid, success boolean, reason text)
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_fraud      REAL;
  v_coherence  REAL;
  v_nid        BIGINT;
  v_uuid       UUID;
  v_chash      TEXT;
BEGIN
  -- For non-collaboration mints, validate PoBW
  IF p_mint_type != 'collaboration' THEN
    SELECT fraud_score, cranial_coherence
    INTO   v_fraud, v_coherence
    FROM   pobw_proofs
    WHERE  id       = p_pobw_id
      AND  twin_id  = p_twin_id
      AND  is_valid = TRUE;

    IF v_fraud IS NULL THEN
      RETURN QUERY SELECT NULL::bigint, NULL::uuid, FALSE,
        'valid PoBW proof required for non-collaboration mint';
      RETURN;
    END IF;
  END IF;

  -- Compute content hash if not provided
  v_chash := COALESCE(p_content_hash,
    encode(sha256((p_twin_id::text || p_snapshot_id::text || NOW()::text)::bytea), 'hex')
  );

  INSERT INTO bio_nft_registry
    (twin_id, snapshot_id, minted_by_bot_id, mint_type,
     content_hash, token_uri, pobw_proof_id,
     fraud_score_at_mint, cranial_coherence_at_mint, collaborator_twin_id)
  VALUES
    (p_twin_id, p_snapshot_id, p_bot_id, p_mint_type,
     v_chash, p_token_uri, p_pobw_id,
     v_fraud, v_coherence, p_collaborator)
  RETURNING id, nft_uuid INTO v_nid, v_uuid;

  RETURN QUERY SELECT v_nid, v_uuid, TRUE, 'NFT registered — pending XRPL anchor'::text;
END;
$function$;

CREATE OR REPLACE FUNCTION public.open_gateway_session(p_twin_id uuid, p_transport transport_medium, p_device text DEFAULT NULL::text, p_firmware text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_id UUID;
BEGIN
    INSERT INTO edge_gateway_sessions (twin_id, transport, device_label, firmware_ver)
    VALUES (p_twin_id, p_transport, p_device, p_firmware)
    RETURNING id INTO v_id;
    RETURN v_id;
END;
$function$;

CREATE OR REPLACE FUNCTION public.prevent_dna_root_exposure()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.shows_dna_root = TRUE THEN
    RAISE EXCEPTION 'collaborator_grants.shows_dna_root can never be TRUE — DNA Root Key is never shared'
      USING ERRCODE = '55000';
  END IF;
  RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.prevent_locked_baseline_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF OLD.is_locked THEN
    RAISE EXCEPTION
      'Calibration baseline % (twin=%, phase=%, node=%) is locked — immutable record',
      OLD.id, OLD.twin_id, OLD.dev_phase, OLD.node_id
      USING ERRCODE = '55000';
  END IF;
  RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.prevent_locked_iab_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF OLD.is_locked THEN
    RAISE EXCEPTION
      'Intent-action baseline % (twin=%, phase=%) is locked — immutable record',
      OLD.id, OLD.twin_id, OLD.dev_phase
      USING ERRCODE = '55000';
  END IF;
  RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.prevent_sealed_snapshot_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF OLD.is_sealed THEN
    RAISE EXCEPTION 'Cannot modify sealed snapshot id=%', OLD.id;
  END IF;
  RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.prevent_tuning_event_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF OLD.is_applied THEN
        RAISE EXCEPTION 'Applied node tuning events are immutable (id=%)', OLD.id
            USING ERRCODE = '55000';
    END IF;
    RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.record_bot_window(p_bot_id bigint, p_twin_id uuid, p_window_at timestamp with time zone, p_active_nodes smallint[], p_motifs jsonb, p_resonance_delta real, p_presigned_hash text, p_action text, p_intervention_type intervention_type DEFAULT NULL::intervention_type, p_trigger_condition text DEFAULT NULL::text, p_trigger_metrics jsonb DEFAULT NULL::jsonb, p_intervention_payload jsonb DEFAULT NULL::jsonb)
 RETURNS TABLE(state_id bigint, intervention_id bigint)
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_sid BIGINT;
  v_iid BIGINT := NULL;
BEGIN
  INSERT INTO node_bot_states
    (bot_id, twin_id, window_at, active_nodes, input_motifs,
     resonance_delta, presigned_token_hash, output_action)
  VALUES
    (p_bot_id, p_twin_id, p_window_at, p_active_nodes, p_motifs,
     p_resonance_delta, p_presigned_hash, p_action)
  RETURNING id INTO v_sid;

  IF p_action = 'intervene' AND p_intervention_type IS NOT NULL THEN
    INSERT INTO bot_intervention_log
      (bot_id, twin_id, intervention_type, target_nodes,
       trigger_condition, trigger_metrics, intervention_payload, state_id)
    VALUES
      (p_bot_id, p_twin_id, p_intervention_type, p_active_nodes,
       p_trigger_condition, p_trigger_metrics, p_intervention_payload, v_sid)
    RETURNING id INTO v_iid;

    UPDATE node_bot_states SET intervention_id = v_iid WHERE id = v_sid;
    UPDATE node_bots SET total_interventions = total_interventions + 1 WHERE id = p_bot_id;
  END IF;

  UPDATE node_bots
  SET last_window_at = p_window_at, total_windows = total_windows + 1
  WHERE id = p_bot_id;

  RETURN QUERY SELECT v_sid, v_iid;
END;
$function$;

CREATE OR REPLACE FUNCTION public.record_chemo_hash(p_twin_id uuid, p_indicator_vector jsonb, p_chemo_salt text, p_chemo_hash text, p_branch_key text, p_access_tier text DEFAULT 'LOW'::text, p_session_id uuid DEFAULT NULL::uuid, p_eeg_provenance text DEFAULT NULL::text, p_stress_state_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_id UUID;
BEGIN
    INSERT INTO chemo_hashes (
        twin_id, indicator_vector, chemo_salt, chemo_hash,
        branch_key, access_tier, session_id,
        eeg_provenance_hash, stress_state_id
    ) VALUES (
        p_twin_id, p_indicator_vector, p_chemo_salt, p_chemo_hash,
        p_branch_key, p_access_tier, p_session_id,
        p_eeg_provenance, p_stress_state_id
    )
    RETURNING id INTO v_id;
    RETURN v_id;
END;
$function$;

CREATE OR REPLACE FUNCTION public.record_p2p_share(p_share_id text, p_source_twin_id uuid, p_target_twin_id uuid, p_handshake_id text, p_data_type text, p_data_hash text, p_payload jsonb DEFAULT NULL::jsonb, p_group_session_id bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
BEGIN
    -- Source's copy
    INSERT INTO p2p_interactions (
        share_id, twin_id, peer_twin_id, handshake_id,
        role, data_type, data_hash, payload, group_session_id
    ) VALUES (
        p_share_id, p_source_twin_id, p_target_twin_id, p_handshake_id,
        'sent', p_data_type, p_data_hash, p_payload, p_group_session_id
    );

    -- Target's copy
    INSERT INTO p2p_interactions (
        share_id, twin_id, peer_twin_id, handshake_id,
        role, data_type, data_hash, payload, group_session_id
    ) VALUES (
        p_share_id, p_target_twin_id, p_source_twin_id, p_handshake_id,
        'received', p_data_type, p_data_hash, p_payload, p_group_session_id
    );

    RETURN jsonb_build_object(
        'success',       TRUE,
        'share_id',      p_share_id,
        'copies_written', 2
    );
END;
$function$;

CREATE OR REPLACE FUNCTION public.register_bio_molecule(p_twin_id uuid, p_sequence text, p_type bio_molecule_type, p_node_id integer DEFAULT NULL::integer, p_gene_symbol text DEFAULT NULL::text, p_source_region text DEFAULT NULL::text, p_chromosome text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_id   BIGINT;
    v_freq REAL;
BEGIN
    INSERT INTO bio_molecule_registry (
        twin_id, linked_node_id, molecule_type,
        nucleotide_sequence, gene_symbol, source_region, chromosome
    ) VALUES (
        p_twin_id, p_node_id, p_type,
        UPPER(TRIM(p_sequence)), p_gene_symbol, p_source_region, p_chromosome
    )
    ON CONFLICT (twin_id, molecule_type, nucleotide_sequence) DO UPDATE
        SET gene_symbol   = COALESCE(EXCLUDED.gene_symbol,   bio_molecule_registry.gene_symbol),
            source_region = COALESCE(EXCLUDED.source_region, bio_molecule_registry.source_region)
    RETURNING id, computed_freq_ghz INTO v_id, v_freq;

    RETURN jsonb_build_object(
        'molecule_id',        v_id,
        'molecule_type',      p_type,
        'computed_freq_ghz',  v_freq,
        'sequence_length_bp', LENGTH(UPPER(TRIM(p_sequence)))
    );
END;
$function$;

CREATE OR REPLACE FUNCTION public.register_bot(p_twin_id uuid, p_bot_class bot_class, p_template_id bigint, p_assigned_nodes smallint[], p_target deployment_target DEFAULT 'gcp_cloudshell'::deployment_target)
 RETURNS TABLE(bot_id bigint, success boolean, reason text)
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_bid BIGINT;
BEGIN
  -- Validate twin exists and is not sealed
  IF NOT EXISTS (
    SELECT 1 FROM twin_identity WHERE id = p_twin_id AND is_sealed = FALSE
  ) THEN
    RETURN QUERY SELECT NULL::bigint, FALSE, 'twin not found or is sealed';
    RETURN;
  END IF;

  -- Validate template exists and matches the bot class
  IF NOT EXISTS (
    SELECT 1 FROM bot_templates WHERE id = p_template_id AND bot_class = p_bot_class
  ) THEN
    RETURN QUERY SELECT NULL::bigint, FALSE, 'template not found or class mismatch';
    RETURN;
  END IF;

  INSERT INTO node_bots
    (twin_id, bot_class, template_id, assigned_nodes, deployment_target)
  VALUES
    (p_twin_id, p_bot_class, p_template_id, p_assigned_nodes, p_target)
  ON CONFLICT (twin_id, bot_class)
  DO UPDATE SET
    template_id       = EXCLUDED.template_id,
    assigned_nodes    = EXCLUDED.assigned_nodes,
    deployment_target = EXCLUDED.deployment_target,
    is_active         = TRUE
  RETURNING id INTO v_bid;

  RETURN QUERY SELECT v_bid, TRUE, 'bot registered'::text;
END;
$function$;

CREATE OR REPLACE FUNCTION public.register_sdr_profile(p_twin_id uuid, p_node_id smallint, p_prf_hz real, p_carrier_freq_ghz real DEFAULT 10.245, p_path_loss_skin_db real DEFAULT 72.0, p_path_loss_air_db real DEFAULT 48.0, p_doppler_baseline_hz real DEFAULT NULL::real, p_doppler_std_hz real DEFAULT NULL::real, p_reflection_sources text[] DEFAULT ARRAY['heart'::text, 'lungs'::text])
 RETURNS TABLE(profile_id bigint, success boolean, reason text)
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_pid BIGINT;
BEGIN
  IF p_prf_hz < 0.83 OR p_prf_hz > 1.1 THEN
    RETURN QUERY SELECT NULL::bigint, FALSE,
      format('PRF %.3f Hz outside 0.83-1.1 Hz SDR band', p_prf_hz);
    RETURN;
  END IF;

  INSERT INTO sdr_node_profiles
    (twin_id, node_id, prf_hz, carrier_freq_ghz,
     path_loss_skin_db, path_loss_air_db,
     bio_doppler_baseline_hz, bio_doppler_std_hz,
     reflection_sources)
  VALUES
    (p_twin_id, p_node_id, p_prf_hz, p_carrier_freq_ghz,
     p_path_loss_skin_db, p_path_loss_air_db,
     p_doppler_baseline_hz, p_doppler_std_hz,
     p_reflection_sources)
  ON CONFLICT (twin_id, node_id) DO UPDATE SET
    prf_hz                    = EXCLUDED.prf_hz,
    carrier_freq_ghz          = EXCLUDED.carrier_freq_ghz,
    path_loss_skin_db         = EXCLUDED.path_loss_skin_db,
    path_loss_air_db          = EXCLUDED.path_loss_air_db,
    bio_doppler_baseline_hz   = EXCLUDED.bio_doppler_baseline_hz,
    bio_doppler_std_hz        = EXCLUDED.bio_doppler_std_hz,
    reflection_sources        = EXCLUDED.reflection_sources,
    calibrated_at             = NOW()
  RETURNING id INTO v_pid;

  -- Sync defaults to the node row itself
  UPDATE mesh_nodes
  SET prf_hz           = p_prf_hz,
      node_carrier_ghz = CASE WHEN p_carrier_freq_ghz = 10.245 THEN NULL
                              ELSE p_carrier_freq_ghz END
  WHERE id = p_node_id;

  RETURN QUERY SELECT v_pid, TRUE, 'SDR profile registered'::text;
END;
$function$;

CREATE OR REPLACE FUNCTION public.request_ephemeral_key(p_snapshot_id integer, p_twin_id uuid, p_key_hash text, p_requester text, p_sig_count smallint DEFAULT 0)
 RETURNS TABLE(key_id bigint, expires_at timestamp with time zone, granted boolean, reason text)
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_tier   snapshot_access_tier;
  v_kid    BIGINT;
  v_exp    TIMESTAMPTZ;
BEGIN
  SELECT access_tier INTO v_tier
  FROM   mesh_frozen_snapshots
  WHERE  id = p_snapshot_id AND twin_id = p_twin_id;

  IF v_tier IS NULL THEN
    RETURN QUERY SELECT NULL::bigint, NULL::timestamptz, FALSE, 'snapshot not found';
    RETURN;
  END IF;

  IF v_tier = 'CRITICAL' THEN
    RETURN QUERY SELECT NULL::bigint, NULL::timestamptz, FALSE,
      'CRITICAL tier: M-DISC vault access only — no digital key issuance';
    RETURN;
  END IF;

  IF v_tier = 'HIGH' AND p_sig_count < 3 THEN
    RETURN QUERY SELECT NULL::bigint, NULL::timestamptz, FALSE,
      format('HIGH tier requires 3-of-5 threshold signatures; %s provided', p_sig_count);
    RETURN;
  END IF;

  v_exp := NOW() + INTERVAL '24 hours';

  INSERT INTO snapshot_ephemeral_keys
    (snapshot_id, twin_id, key_hash, expires_at, issued_to, sig_count)
  VALUES
    (p_snapshot_id, p_twin_id, p_key_hash, v_exp, p_requester, p_sig_count)
  RETURNING id INTO v_kid;

  RETURN QUERY SELECT v_kid, v_exp, TRUE, 'ephemeral key issued'::text;
END;
$function$;

CREATE OR REPLACE FUNCTION public.request_vault_destruction(p_snapshot_id integer, p_twin_id uuid, p_witness text, p_confirm boolean DEFAULT false)
 RETURNS TABLE(vault_id bigint, status text, success boolean)
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_vid BIGINT;
BEGIN
  SELECT id INTO v_vid
  FROM   snapshot_vault_records
  WHERE  snapshot_id = p_snapshot_id AND twin_id = p_twin_id;

  IF v_vid IS NULL THEN
    RETURN QUERY SELECT NULL::bigint, 'vault record not found'::text, FALSE;
    RETURN;
  END IF;

  IF NOT p_confirm THEN
    UPDATE snapshot_vault_records
    SET    destruction_requested_at = NOW(), destruction_witness = p_witness
    WHERE  id = v_vid;
    RETURN QUERY SELECT v_vid, 'destruction requested — physical disc must be destroyed before confirmation'::text, TRUE;
  ELSE
    UPDATE snapshot_vault_records
    SET    destruction_confirmed_at = NOW()
    WHERE  id = v_vid AND destruction_requested_at IS NOT NULL;

    IF NOT FOUND THEN
      RETURN QUERY SELECT v_vid, 'destruction must be requested before it can be confirmed'::text, FALSE;
      RETURN;
    END IF;

    -- Seal the snapshot as permanently inaccessible
    UPDATE mesh_frozen_snapshots
    SET    metadata = COALESCE(metadata, '{}'::jsonb)
             || jsonb_build_object('destruction_confirmed_at', NOW(), 'destruction_witness', p_witness)
    WHERE  id = p_snapshot_id;

    RETURN QUERY SELECT v_vid, 'destruction confirmed — snapshot permanently sealed'::text, TRUE;
  END IF;
END;
$function$;

CREATE OR REPLACE FUNCTION public.revoke_p2p_connection(p_revoking_twin_id uuid, p_peer_twin_id uuid, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
    v_a     UUID    := LEAST(p_revoking_twin_id, p_peer_twin_id);
    v_b     UUID    := GREATEST(p_revoking_twin_id, p_peer_twin_id);
    v_rows  INTEGER;
BEGIN
    UPDATE p2p_connections
    SET state             = 'revoked',
        revoked_by        = p_revoking_twin_id,
        revoked_at        = NOW(),
        revocation_reason = p_reason
    WHERE twin_id_a = v_a AND twin_id_b = v_b
      AND state = 'active';

    GET DIAGNOSTICS v_rows = ROW_COUNT;

    IF v_rows = 0 THEN
        RETURN jsonb_build_object('success', FALSE, 'reason', 'No active connection found');
    END IF;

    RETURN jsonb_build_object(
        'success',    TRUE,
        'revoked_by', p_revoking_twin_id,
        'revoked_at', NOW()
    );
END;
$function$;

CREATE OR REPLACE FUNCTION public.rls_auto_enable()
 RETURNS event_trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$function$;

CREATE OR REPLACE FUNCTION public.set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  new.updated_at = now();
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.trace_relay_path(p_twin_id uuid, p_sensor_id text, p_source_node_id smallint, p_relay_node_id smallint, p_destination_node_id smallint, p_source_phase_rad real, p_relay_phase_rad real, p_destination_phase_rad real, p_carrier_freq_ghz real DEFAULT 10.245, p_prf_hz real DEFAULT NULL::real, p_source_medium propagation_medium DEFAULT 'skin'::propagation_medium, p_relay_medium propagation_medium DEFAULT 'body_coupled'::propagation_medium, p_operation text DEFAULT NULL::text, p_snapshot_id integer DEFAULT NULL::integer, p_heart_reflection boolean DEFAULT false, p_lung_reflection boolean DEFAULT false, p_session_id bigint DEFAULT NULL::bigint)
 RETURNS TABLE(relay_id bigint, phase_coherence real, signature_matched boolean, threshold_sig_id bigint, total_loss_db real, verdict text)
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_rid          BIGINT;
  v_tsig_id      BIGINT := NULL;
  v_coherence    REAL;
  v_matched      BOOLEAN;
  v_threshold    REAL := 0.85;
  v_src_loss     REAL;
  v_rel_loss     REAL;
  v_total_loss   REAL;
  v_path         SMALLINT[];
  v_loss_anomaly BOOLEAN := FALSE;
  v_src_profile  RECORD;
  v_dst_profile  RECORD;
  -- Expected path loss lookup
  v_expected_loss REAL;
  v_nonce        TEXT;
BEGIN
  -- Build the propagation path array
  IF p_relay_node_id IS NOT NULL THEN
    v_path := ARRAY[p_source_node_id, p_relay_node_id, p_destination_node_id];
  ELSE
    v_path := ARRAY[p_source_node_id, p_destination_node_id];
  END IF;

  -- Fetch SDR profiles for path loss calculation
  SELECT path_loss_skin_db, path_loss_air_db, path_loss_body_coupled_db
  INTO   v_src_profile
  FROM   sdr_node_profiles
  WHERE  twin_id = p_twin_id AND node_id = p_source_node_id;

  -- Source-to-relay segment loss
  v_src_loss := CASE p_source_medium
    WHEN 'skin'         THEN COALESCE(v_src_profile.path_loss_skin_db, 72.0)
    WHEN 'air'          THEN COALESCE(v_src_profile.path_loss_air_db, 48.0)
    WHEN 'body_coupled' THEN COALESCE(v_src_profile.path_loss_body_coupled_db, 60.0)
    ELSE 60.0
  END;

  -- Relay-to-destination segment loss (body-coupled default)
  v_rel_loss := CASE p_relay_medium
    WHEN 'skin'         THEN 72.0
    WHEN 'air'          THEN 48.0
    WHEN 'body_coupled' THEN 60.0
    ELSE 60.0
  END;

  v_total_loss := CASE
    WHEN p_relay_node_id IS NOT NULL THEN v_src_loss + v_rel_loss
    ELSE v_src_loss
  END;

  -- Phase coherence: cosine similarity corrected for phase wrapping
  -- cos(dest - source) normalised to [0,1]
  v_coherence := (1.0 + COS(p_destination_phase_rad - p_source_phase_rad)) / 2.0;

  -- Boost coherence when internal reflections are present —
  -- biological body provides a coherence floor that external probes cannot match
  IF p_heart_reflection THEN
    v_coherence := LEAST(1.0, v_coherence + 0.05);
  END IF;
  IF p_lung_reflection THEN
    v_coherence := LEAST(1.0, v_coherence + 0.03);
  END IF;

  -- Look up calibrated match threshold for this pair
  SELECT match_threshold INTO v_threshold
  FROM   phase_coherence_baselines
  WHERE  twin_id    = p_twin_id
    AND  node_a_id  = LEAST(p_source_node_id, p_destination_node_id)
    AND  node_b_id  = GREATEST(p_source_node_id, p_destination_node_id)
  ORDER BY locked_at DESC NULLS LAST
  LIMIT 1;

  v_threshold := COALESCE(v_threshold, 0.85);
  v_matched   := v_coherence >= v_threshold;

  -- Expected path loss check
  v_expected_loss := CASE p_source_medium
    WHEN 'skin' THEN 72.0 WHEN 'air' THEN 48.0 ELSE 60.0
  END;
  v_loss_anomaly := ABS(v_src_loss - v_expected_loss) > 15.0;

  -- Write threshold signature if matched and operation is specified
  IF v_matched AND p_operation IS NOT NULL AND p_snapshot_id IS NOT NULL THEN
    v_nonce := encode(
      sha256((p_twin_id::text || p_operation || NOW()::text)::bytea),
      'hex'
    );
    INSERT INTO snapshot_threshold_sigs
      (snapshot_id, signer_index, signature, operation, nonce)
    VALUES
      (p_snapshot_id,
       -- Use destination node_id as the signer_index modulo 5 (1-5 range)
       ((p_destination_node_id % 5) + 1)::smallint,
       encode(sha256((p_source_phase_rad::text || p_destination_phase_rad::text || v_nonce)::bytea), 'hex'),
       p_operation, v_nonce)
    ON CONFLICT DO NOTHING
    RETURNING id INTO v_tsig_id;
  END IF;

  INSERT INTO relay_path_events
    (twin_id, sensor_id, source_node_id, relay_node_id, destination_node_id,
     propagation_path, source_phase_rad, relay_phase_rad, destination_phase_rad,
     source_to_relay_loss_db, relay_to_dest_loss_db, total_path_loss_db,
     source_medium, relay_medium,
     carrier_freq_ghz, prf_hz,
     phase_coherence, match_threshold, signature_matched, operation,
     threshold_sig_id,
     heart_reflection_present, lung_reflection_present, path_loss_anomaly,
     session_id)
  VALUES
    (p_twin_id, p_sensor_id, p_source_node_id, p_relay_node_id, p_destination_node_id,
     v_path, p_source_phase_rad, p_relay_phase_rad, p_destination_phase_rad,
     v_src_loss, v_rel_loss, v_total_loss,
     p_source_medium, p_relay_medium,
     p_carrier_freq_ghz, p_prf_hz,
     v_coherence, v_threshold, v_matched, p_operation,
     v_tsig_id,
     p_heart_reflection, p_lung_reflection, v_loss_anomaly,
     p_session_id)
  RETURNING id INTO v_rid;

  RETURN QUERY SELECT
    v_rid,
    v_coherence,
    v_matched,
    v_tsig_id,
    v_total_loss,
    CASE
      WHEN NOT v_matched AND v_loss_anomaly
        THEN 'REJECTED — coherence below threshold AND path loss anomaly detected'
      WHEN NOT v_matched
        THEN format('REJECTED — coherence %.3f < threshold %.3f', v_coherence, v_threshold)
      WHEN v_matched AND p_heart_reflection AND p_lung_reflection
        THEN format('MATCHED — coherence %.3f (heart+lung reflections confirmed in-body origin)', v_coherence)
      WHEN v_matched
        THEN format('MATCHED — coherence %.3f', v_coherence)
      ELSE 'INDETERMINATE'
    END::text;
END;
$function$;

CREATE OR REPLACE FUNCTION public.trigger_twin_sync_lock(p_twin_id uuid, p_session_id bigint, p_sensor_id text, p_intensity real, p_window_end timestamp with time zone DEFAULT now())
 RETURNS TABLE(lock_id bigint, composite_hash text, token_count integer, snapshot_id integer, pobw_id bigint, nft_id bigint, success boolean, reason text)
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_window_start  TIMESTAMPTZ := p_window_end - INTERVAL '5 seconds';
  v_tokens        TEXT[];
  v_composite     TEXT;
  v_lid           BIGINT;
  v_snap_id       INT;
  v_pobw_id       BIGINT;
  v_nft_id        BIGINT;
  v_snap_hash     TEXT;
  v_prev_hash     TEXT;
  v_chain_hash    TEXT;
  v_pobw_hash     TEXT;
  v_bot_id        BIGINT;
BEGIN
  IF p_intensity <= 0.7 THEN
    RETURN QUERY SELECT NULL::bigint, NULL::text, 0, NULL::int,
                        NULL::bigint, NULL::bigint, FALSE,
                        format('intensity %.2f <= 0.7 — shock threshold not reached', p_intensity);
    RETURN;
  END IF;

  -- Prevent duplicate locks within 5 seconds for the same session
  IF EXISTS (
    SELECT 1 FROM twin_sync_lock_events
    WHERE session_id  = p_session_id
      AND triggered_at > p_window_end - INTERVAL '5 seconds'
  ) THEN
    RETURN QUERY SELECT NULL::bigint, NULL::text, 0, NULL::int,
                        NULL::bigint, NULL::bigint, FALSE,
                        'duplicate lock suppressed — previous lock within 5s window';
    RETURN;
  END IF;

  -- Collect token hashes from node_bot_states for the last 5 seconds
  SELECT ARRAY_AGG(presigned_token_hash ORDER BY window_at)
  INTO   v_tokens
  FROM   node_bot_states
  WHERE  twin_id     = p_twin_id
    AND  window_at BETWEEN v_window_start AND p_window_end
    AND  presigned_token_hash IS NOT NULL;

  IF v_tokens IS NULL OR array_length(v_tokens, 1) = 0 THEN
    -- Fall back to corpus frame tokens if no bot windows are present
    SELECT ARRAY_AGG(frame_hash ORDER BY timestamp_s)
    INTO   v_tokens
    FROM   corpus_simulation_frames
    WHERE  session_id = p_session_id
      AND  timestamp_s BETWEEN
             EXTRACT(EPOCH FROM (p_window_end - v_window_start))::int - 5
             AND EXTRACT(EPOCH FROM (p_window_end - v_window_start))::int;
  END IF;

  v_tokens := COALESCE(v_tokens, ARRAY['no_tokens_in_window']);

  -- Composite hash = SHA-256(concatenation of all tokens in order)
  v_composite := encode(
    sha256(array_to_string(v_tokens, '')::bytea),
    'hex'
  );

  -- Look up the cranial bot for this twin
  SELECT id INTO v_bot_id
  FROM node_bots
  WHERE twin_id = p_twin_id AND bot_class = 'cranial' AND is_active = TRUE
  LIMIT 1;

  -- Create frozen snapshot for the shock window
  SELECT chain_hash INTO v_prev_hash
  FROM   mesh_frozen_snapshots
  WHERE  twin_id = p_twin_id
  ORDER BY captured_at DESC
  LIMIT 1;

  v_prev_hash := COALESCE(v_prev_hash, REPEAT('0', 64));

  v_snap_hash  := encode(sha256(v_composite::bytea), 'hex');
  v_chain_hash := encode(sha256((v_prev_hash || v_snap_hash)::bytea), 'hex');

  INSERT INTO mesh_frozen_snapshots
    (twin_id, label, captured_at, node_count,
     snapshot_hash, prev_hash, chain_hash,
     is_sealed, sealed_at,
     access_tier, dev_phase,
     metadata)
  VALUES
    (p_twin_id,
     format('twin_sync_lock | intensity=%.2f | session=%s', p_intensity, p_session_id),
     p_window_end, 26,
     v_snap_hash, v_prev_hash, v_chain_hash,
     TRUE, p_window_end,
     'LOW',
     'ADULT',
     jsonb_build_object(
       'trigger', 'twin_sync_lock',
       'intensity', p_intensity,
       'sim_state', 'HIGH_STRESS_SHOCK',
       'composite_hash', v_composite,
       'token_count', array_length(v_tokens, 1)
     ))
  RETURNING id INTO v_snap_id;

  -- Generate PoBW proof for the shock window
  v_pobw_hash := encode(
    sha256((p_twin_id::text || p_window_end::text || v_composite)::bytea),
    'hex'
  );

  INSERT INTO pobw_proofs
    (twin_id, bot_id, window_start, window_end, window_duration_s,
     cranial_coherence, fraud_score,
     is_valid, validity_reason, proof_hash)
  VALUES
    (p_twin_id, v_bot_id, v_window_start, p_window_end, 5.0,
     0.0,   -- coherence is zero at shock — this is a distress proof, not focus proof
     0.0,   -- fraud_score = 0 because the shock was biologically triggered
     TRUE, 'twin_sync_lock: HIGH_STRESS_SHOCK event anchored', v_pobw_hash)
  RETURNING id INTO v_pobw_id;

  -- Mint Bio-NFT (pending XRPL anchor)
  INSERT INTO bio_nft_registry
    (twin_id, snapshot_id, minted_by_bot_id, mint_type,
     content_hash, pobw_proof_id,
     fraud_score_at_mint, cranial_coherence_at_mint,
     metadata)
  VALUES
    (p_twin_id, v_snap_id, v_bot_id, 'life_event',
     v_composite, v_pobw_id,
     0.0, 0.0,
     jsonb_build_object(
       'trigger', 'twin_sync_lock',
       'intensity', p_intensity,
       'composite_hash', v_composite,
       'session_id', p_session_id
     ))
  RETURNING id INTO v_nft_id;

  -- Create the sync lock event record
  INSERT INTO twin_sync_lock_events
    (twin_id, session_id, sensor_id, triggered_at,
     lock_window_start, lock_window_end, intensity_at_trigger,
     token_hashes, token_count, composite_hash,
     snapshot_id, pobw_id, nft_id)
  VALUES
    (p_twin_id, p_session_id, p_sensor_id, p_window_end,
     v_window_start, p_window_end, p_intensity,
     v_tokens, array_length(v_tokens, 1), v_composite,
     v_snap_id, v_pobw_id, v_nft_id)
  RETURNING id INTO v_lid;

  -- Update session counters
  UPDATE corpus_simulation_sessions
  SET sync_lock_count = sync_lock_count + 1,
      snapshot_id     = v_snap_id
  WHERE id = p_session_id;

  RETURN QUERY SELECT
    v_lid, v_composite, array_length(v_tokens, 1),
    v_snap_id, v_pobw_id, v_nft_id, TRUE,
    'twin_sync_lock committed — pending XRPL anchor'::text;
END;
$function$;

CREATE OR REPLACE FUNCTION public.verify_biological_integrity(p_twin_id uuid, p_origin_node_id smallint, p_terminal_node_id smallint, p_origin_at timestamp with time zone, p_terminal_at timestamp with time zone, p_sensor_id text)
 RETURNS TABLE(event_id bigint, transit_ms real, baseline_mean_ms real, baseline_std_ms real, deviation_sigma real, fraud_score real, is_synthetic boolean, verdict text)
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_transit    REAL;
  v_base       RECORD;
  v_dev_sigma  REAL;
  v_fraud      REAL;
  v_synthetic  BOOLEAN;
  v_eid        BIGINT;
  v_anid       BIGINT;
BEGIN
  v_transit := EXTRACT(EPOCH FROM (p_terminal_at - p_origin_at)) * 1000.0;

  -- Find the most recent locked baseline for this origin→terminal pair
  SELECT *
  INTO   v_base
  FROM   intent_action_baselines
  WHERE  twin_id          = p_twin_id
    AND  origin_node_id   = p_origin_node_id
    AND  terminal_node_id = p_terminal_node_id
    AND  is_locked        = TRUE
  ORDER BY locked_at DESC
  LIMIT 1;

  IF v_base IS NULL THEN
    -- No calibration baseline exists; record the transit but cannot score it
    INSERT INTO intent_action_events
      (twin_id, sensor_id, detected_at, origin_node_id, terminal_node_id,
       origin_at, terminal_at, transit_ms, fraud_score, is_synthetic)
    VALUES
      (p_twin_id, p_sensor_id, NOW(), p_origin_node_id, p_terminal_node_id,
       p_origin_at, p_terminal_at, v_transit, 0, FALSE)
    RETURNING id INTO v_eid;

    RETURN QUERY SELECT v_eid, v_transit, NULL::real, NULL::real,
                        NULL::real, 0::real, FALSE,
                        'no calibration baseline — transit recorded, scoring deferred'::text;
    RETURN;
  END IF;

  -- Compute deviation in standard deviations
  v_dev_sigma := CASE
    WHEN v_base.std_transit_ms = 0 THEN 0
    ELSE (v_transit - v_base.mean_transit_ms) / v_base.std_transit_ms
  END;

  -- Fraud score: sigmoid-like normalisation; |3σ| → ~0.95, |5σ| → ~1.0
  v_fraud     := LEAST(1.0, ABS(v_dev_sigma) / 5.0);

  -- Synthetic flag: outside ±3σ calibration bounds
  v_synthetic := ABS(v_dev_sigma) > 3.0;

  -- Write event
  INSERT INTO intent_action_events
    (twin_id, sensor_id, detected_at, origin_node_id, terminal_node_id,
     origin_at, terminal_at, transit_ms,
     baseline_id, baseline_mean_ms, baseline_std_ms,
     deviation_sigma, fraud_score, is_synthetic)
  VALUES
    (p_twin_id, p_sensor_id, NOW(), p_origin_node_id, p_terminal_node_id,
     p_origin_at, p_terminal_at, v_transit,
     v_base.id, v_base.mean_transit_ms, v_base.std_transit_ms,
     v_dev_sigma, v_fraud, v_synthetic)
  RETURNING id INTO v_eid;

  -- If synthetic, raise a PATTERN_INJECTION anomaly
  IF v_synthetic THEN
    INSERT INTO mesh_anomalies
      (twin_id, detected_at, anomaly_type, affected_nodes, deviation_score,
       alert_level, metadata)
    VALUES
      (p_twin_id, NOW(), 'PATTERN_INJECTION',
       ARRAY[p_origin_node_id::int, p_terminal_node_id::int],
       v_fraud,
       CASE WHEN ABS(v_dev_sigma) > 5 THEN 'CRITICAL' ELSE 'WARNING' END,
       jsonb_build_object(
         'transit_ms',       v_transit,
         'baseline_mean_ms', v_base.mean_transit_ms,
         'deviation_sigma',  v_dev_sigma,
         'fraud_score',      v_fraud,
         'calibration_phase', v_base.dev_phase,
         'intent_action_event_id', v_eid
       ))
    RETURNING id INTO v_anid;

    UPDATE intent_action_events SET anomaly_id = v_anid WHERE id = v_eid;
  END IF;

  RETURN QUERY SELECT
    v_eid,
    v_transit,
    v_base.mean_transit_ms,
    v_base.std_transit_ms,
    v_dev_sigma,
    v_fraud,
    v_synthetic,
    CASE
      WHEN NOT v_synthetic            THEN 'AUTHENTIC — within calibration bounds'
      WHEN ABS(v_dev_sigma) <= 5.0    THEN 'WARNING — outside ±3σ calibration baseline (possible synthetic)'
      ELSE                                 'CRITICAL — outside ±5σ: PATTERN_INJECTION likely'
    END::text AS verdict;
END;
$function$;


